    assert coord.stream_error_at == {}
    assert coord.stream_fell_back == {}
    assert coord.local_rescue_attempts == {}
    assert coord.local_rescue_at == {}
    assert coord.lan_tcp_reachable == {}
    assert coord.local_promote_at == {}
