# Regression — entity_id migration for v11.0.0 doubled-prefix bug.
# v11.0.0 Gold-Compliance migration set `_attr_has_entity_name = True`
# on 30+ entity classes without removing the device-name prefix from
# their `_attr_name`. HA prepended the device name a second time and the
# buggy entity_id (e.g. `button.bosch_est_bosch_est_refresh_snapshot`)
# stuck in the entity_registry for every install that went through that
# release.
# v12.3.0 fixes the source; this test pins the migration helper that
# renames the surviving buggy entries on next setup.


class TestDoubledPrefixRegex:
    """The regex is the load-bearing piece — pin it directly."""

    @pytest.mark.parametrize(
        "eid, expect_domain, expect_slug, expect_rest",
        [
            (
                "button.bosch_est_bosch_est_refresh_snapshot",
                "button",
                "est",
                "refresh_snapshot",
            ),
            ("button.bosch_est_bosch_est_siren", "button", "est", "siren"),
            ("update.bosch_est_bosch_est_firmware", "update", "est", "firmware"),
            (
                "number.bosch_terrasse_bosch_terrasse_pan_position",
                "number",
                "terrasse",
                "pan_position",
            ),
            (
                "select.bosch_innenbereich_bosch_innenbereich_video_quality",
                "select",
                "innenbereich",
                "video_quality",
            ),
            (
                "light.bosch_garten_bosch_garten_frontlicht",
                "light",
                "garten",
                "frontlicht",
            ),
            (
                "binary_sensor.bosch_kamera_bosch_kamera_motion",
                "binary_sensor",
                "kamera",
                "motion",
            ),
            # multi-word slug
            (
                "number.bosch_eyes_outdoor_ii_bosch_eyes_outdoor_ii_lens_elevation",
                "number",
                "eyes_outdoor_ii",
                "lens_elevation",
            ),
        ],
    )
    def test_buggy_entity_ids_match(
        self, eid: str, expect_domain: str, expect_slug: str, expect_rest: str
    ):
        m = _DOUBLED_PREFIX_RE.match(eid)
        assert m is not None, f"Should have matched: {eid}"
        assert m.group(1) == expect_domain
        assert m.group(2) == expect_slug
        assert m.group(3) == expect_rest

    @pytest.mark.parametrize(
        "eid",
        [
            # already-correct entity_ids must NOT match
            "button.bosch_est_refresh_snapshot",
            "number.bosch_terrasse_pan_position",
            "select.bosch_innenbereich_video_quality",
            # camera and switch domains are never buggy — fence them out of the regex
            "camera.bosch_terrasse",
            "switch.bosch_terrasse_live_stream",
            "sensor.bosch_terrasse_fcm_push_status",
            # not our integration at all
            "button.living_room_lamp",
            "switch.bosch_terrasse_bosch_terrasse_live_stream",  # switch not in domain list
            # legitimate doubled token that's NOT a doubled prefix (slug doesn't repeat)
            "button.bosch_est_bosch_west_refresh_snapshot",
        ],
    )
    def test_clean_entity_ids_do_not_match(self, eid: str):
        m = _DOUBLED_PREFIX_RE.match(eid)
        assert m is None, f"Should NOT have matched: {eid}"


class TestMigrateDoubledPrefix:
    """End-to-end migration against a real HA entity_registry."""

    @pytest.fixture
    def config_entry(self, hass: HomeAssistant) -> MockConfigEntry:
        entry = MockConfigEntry(
            domain=DOMAIN,
            data={"bearer_token": "tok", "refresh_token": "rt"},
            unique_id=DOMAIN,
        )
        entry.add_to_hass(hass)
        return entry

    async def test_renames_buggy_entity_ids(
        self, hass: HomeAssistant, config_entry: MockConfigEntry
    ):
        """Buggy entries are renamed; non-buggy ones are untouched."""
        ent_reg = er.async_get(hass)
        # 3 buggy entries (button refresh + button siren + update firmware)
        e1 = ent_reg.async_get_or_create(
            "button",
            DOMAIN,
            "bosch_shc_refresh_camid1",
            suggested_object_id="bosch_est_bosch_est_refresh_snapshot",
            config_entry=config_entry,
        )
        e2 = ent_reg.async_get_or_create(
            "button",
            DOMAIN,
            "bosch_shc_siren_camid1",
            suggested_object_id="bosch_est_bosch_est_siren",
            config_entry=config_entry,
        )
        e3 = ent_reg.async_get_or_create(
            "update",
            DOMAIN,
            "bosch_shc_camera_camid1_firmware_update",
            suggested_object_id="bosch_est_bosch_est_firmware",
            config_entry=config_entry,
        )
        # 1 already-correct entry (must NOT be renamed)
        e4 = ent_reg.async_get_or_create(
            "switch",
            DOMAIN,
            "bosch_shc_live_stream_camid1",
            suggested_object_id="bosch_est_live_stream",
            config_entry=config_entry,
        )
        # 1 unrelated entity (different config entry, must NOT be touched)
        other_entry = MockConfigEntry(domain="other", data={}, unique_id="other")
        other_entry.add_to_hass(hass)
        e5 = ent_reg.async_get_or_create(
            "button",
            "other",
            "external_uid",
            suggested_object_id="bosch_est_bosch_est_refresh_snapshot",
            config_entry=other_entry,
        )

        count = await _migrate_doubled_prefix_entity_ids(hass, config_entry.entry_id)

        assert count == 3
        # buggy got renamed
        assert ent_reg.async_get(e1.entity_id) is None
        assert ent_reg.async_get("button.bosch_est_refresh_snapshot") is not None
        assert ent_reg.async_get(e2.entity_id) is None
        assert ent_reg.async_get("button.bosch_est_siren") is not None
        assert ent_reg.async_get(e3.entity_id) is None
        assert ent_reg.async_get("update.bosch_est_firmware") is not None
        # correct one untouched
        assert ent_reg.async_get(e4.entity_id) is not None
        # other-integration entity untouched
        assert ent_reg.async_get(e5.entity_id) is not None

    async def test_creates_repair_issue_when_renames_happen(
        self, hass: HomeAssistant, config_entry: MockConfigEntry
    ):
        ent_reg = er.async_get(hass)
        ent_reg.async_get_or_create(
            "button",
            DOMAIN,
            "uid1",
            suggested_object_id="bosch_est_bosch_est_refresh_snapshot",
            config_entry=config_entry,
        )
        ent_reg.async_get_or_create(
            "number",
            DOMAIN,
            "uid2",
            suggested_object_id="bosch_est_bosch_est_pan_position",
            config_entry=config_entry,
        )

        issue_reg = ir.async_get(hass)
        await _migrate_doubled_prefix_entity_ids(hass, config_entry.entry_id)
        issue = issue_reg.async_get_issue(DOMAIN, "doubled_prefix_entity_ids_migrated")
        assert issue is not None
        assert issue.severity == ir.IssueSeverity.WARNING
        assert issue.is_fixable is False
        assert issue.translation_placeholders["count"] == "2"

    async def test_examples_truncated_with_ellipsis_when_more_than_five(
        self,
        hass: HomeAssistant,
        config_entry: MockConfigEntry,
    ):
        """When >5 entries are renamed, the repair-issue `examples` field is
        truncated to the first 5 followed by ', …'. Pins L5103."""
        ent_reg = er.async_get(hass)
        slugs = ["a", "b", "c", "d", "e", "f", "g"]
        for slug in slugs:
            ent_reg.async_get_or_create(
                "button",
                DOMAIN,
                f"uid_{slug}",
                suggested_object_id=f"bosch_{slug}_bosch_{slug}_refresh_snapshot",
                config_entry=config_entry,
            )
        count = await _migrate_doubled_prefix_entity_ids(hass, config_entry.entry_id)
        assert count == 7
        issue = ir.async_get(hass).async_get_issue(
            DOMAIN,
            "doubled_prefix_entity_ids_migrated",
        )
        assert issue is not None
        examples = issue.translation_placeholders["examples"]
        # Exactly five "old → new" pairs (one per slug) plus the truncation marker.
        assert examples.count("→") == 5
        assert examples.endswith(", …")

    async def test_no_issue_when_no_buggy_entries(
        self, hass: HomeAssistant, config_entry: MockConfigEntry
    ):
        ent_reg = er.async_get(hass)
        ent_reg.async_get_or_create(
            "switch",
            DOMAIN,
            "uid1",
            suggested_object_id="bosch_est_live_stream",
            config_entry=config_entry,
        )
        issue_reg = ir.async_get(hass)
        # Pre-seed the issue to verify it gets deleted on a clean run
        ir.async_create_issue(
            hass,
            DOMAIN,
            "doubled_prefix_entity_ids_migrated",
            is_fixable=False,
            severity=ir.IssueSeverity.WARNING,
            translation_key="doubled_prefix_entity_ids_migrated",
        )
        assert (
            issue_reg.async_get_issue(DOMAIN, "doubled_prefix_entity_ids_migrated")
            is not None
        )

        count = await _migrate_doubled_prefix_entity_ids(hass, config_entry.entry_id)
        assert count == 0
        assert (
            issue_reg.async_get_issue(DOMAIN, "doubled_prefix_entity_ids_migrated")
            is None
        )

    async def test_skips_when_new_entity_id_already_exists(
        self, hass: HomeAssistant, config_entry: MockConfigEntry
    ):
        """Defensive: if both buggy and correct entries somehow coexist,
        skip rather than raise on the unique-entity_id constraint."""
        ent_reg = er.async_get(hass)
        ent_reg.async_get_or_create(
            "button",
            DOMAIN,
            "uid_old",
            suggested_object_id="bosch_est_bosch_est_refresh_snapshot",
            config_entry=config_entry,
        )
        ent_reg.async_get_or_create(
            "button",
            DOMAIN,
            "uid_new",
            suggested_object_id="bosch_est_refresh_snapshot",
            config_entry=config_entry,
        )

        count = await _migrate_doubled_prefix_entity_ids(hass, config_entry.entry_id)
        assert count == 0
        # both still exist
        assert (
            ent_reg.async_get("button.bosch_est_bosch_est_refresh_snapshot") is not None
        )
        assert ent_reg.async_get("button.bosch_est_refresh_snapshot") is not None


# Tests for token-refresh logic in BoschCameraCoordinator.
# Token refresh is the single most common pain point in OAuth integrations —
# historically the source of GH#2 (token refresh fails) and GH#5 (refresh-
# token 404). The current implementation has 3 retries, server-outage backoff,
# in-memory + entry-data persistence, and a refresh-token rotation guard.
# These tests pin the contract of `_token_still_valid` (JWT exp parsing)
# and `_token_failure_alert_sent` flag handling. The actual HTTP refresh
# flow is tested elsewhere (config_flow_helpers).


def _make_jwt(exp_offset_sec: int = 3600) -> str:
    """Build a fake JWT with the given exp offset from now.

    Positive offset = valid for X seconds.
    Negative offset = expired X seconds ago.
    """
    header = (
        base64.urlsafe_b64encode(json.dumps({"alg": "RS256", "typ": "JWT"}).encode())
        .rstrip(b"=")
        .decode()
    )
    payload = (
        base64.urlsafe_b64encode(
            json.dumps(
                {
                    "exp": int(_time.time()) + exp_offset_sec,
                    "iat": int(_time.time()),
                    "sub": "user-1",
                }
            ).encode()
        )
        .rstrip(b"=")
        .decode()
    )
    return f"{header}.{payload}.fake-signature"


class TestTokenStillValid:
    def _make_coord(self, token: str):
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord = SimpleNamespace(
            entry=SimpleNamespace(data={"bearer_token": token}),
            _refreshed_token=None,
        )
        # Bind methods we need
        coord.token = BoschCameraCoordinator.token.fget(coord)
        return coord, BoschCameraCoordinator._token_still_valid

    def test_valid_token_returns_true(self):
        token = _make_jwt(exp_offset_sec=3600)  # 1 hour from now
        coord, method = self._make_coord(token)
        assert method(coord, min_remaining=60) is True

    def test_expiring_within_min_remaining_returns_false(self):
        """Token expires in 30s, min_remaining=60 → not valid enough."""
        token = _make_jwt(exp_offset_sec=30)
        coord, method = self._make_coord(token)
        assert method(coord, min_remaining=60) is False

    def test_already_expired_returns_false(self):
        token = _make_jwt(exp_offset_sec=-300)  # 5 min ago
        coord, method = self._make_coord(token)
        assert method(coord, min_remaining=60) is False

    def test_empty_token_returns_false(self):
        coord, method = self._make_coord("")
        assert method(coord, min_remaining=60) is False

    def test_malformed_jwt_returns_false(self):
        """JWT with only 1 dot-segment must not crash."""
        coord, method = self._make_coord("only.one")
        assert method(coord, min_remaining=60) is False

    def test_garbage_token_returns_false(self):
        """Random string — base64 decode fails — must not crash."""
        coord, method = self._make_coord("not.a-valid_jwt")
        assert method(coord, min_remaining=60) is False

    def test_jwt_without_exp_treated_as_expired(self):
        """Payload without `exp` claim → exp.get(0) = 0 → expired."""
        header = base64.urlsafe_b64encode(b'{"alg":"RS256"}').rstrip(b"=").decode()
        payload = base64.urlsafe_b64encode(b'{"sub":"u"}').rstrip(b"=").decode()
        token = f"{header}.{payload}.sig"
        coord, method = self._make_coord(token)
        assert method(coord, min_remaining=60) is False

    def test_zero_min_remaining_accepts_valid_token(self):
        """min_remaining=0 → any not-yet-expired token is valid."""
        token = _make_jwt(exp_offset_sec=10)
        coord, method = self._make_coord(token)
        assert method(coord, min_remaining=0) is True

    def test_min_remaining_at_boundary(self):
        """A token expiring in exactly min_remaining seconds is valid (>=)."""
        # We can't hit this exactly due to time progression — give a
        # comfortable margin and test a slightly-larger value works.
        token = _make_jwt(exp_offset_sec=120)
        coord, method = self._make_coord(token)
        assert method(coord, min_remaining=60) is True


# Root cause: the 401 rescue (`handle_stream_worker_error`) and the proxy-died
# rebuild (`on_tls_proxy_died`) tore the old TLS proxy down with an external
# `await self.stop_tls_proxy(cam_id)` BEFORE calling `try_live_connection(...)`.
# That stop ran OUTSIDE the per-cam stream lock. A concurrent renewal/heartbeat
# (`try_live_connection(is_renewal=True)`) holds that lock across the whole
# proxy rebuild (PUT /connection + pre-warm, several seconds of awaits). If the
# rescue's external stop landed while the renewal held the lock mid-rebuild, it
# killed the port the renewal had just started — and the rescue's own
# `try_live_connection(is_renewal=False)` then SKIPPED (lock held), leaving
# go2rtc + HA Stream pinned to the dead proxy port → frozen image.
# Fix: the teardown moved INSIDE `try_live_connection_inner`, guarded by a new
# `force_reset` flag, so the stop-old-proxy + rebuild are atomic under the lock.
# The recovery callers pass `force_reset=True`, which also makes the public
# `try_live_connection` WAIT for the lock instead of skipping.
# These tests pin:
# 1. `force_reset=True` tears down (pop live + discard warming + stop proxy)
# at the top of the inner builder.
# 2. `force_reset=False` does NOT tear anything down (opportunistic callers).
# 3. The lock-skip guard exempts `force_reset` (so recovery waits, not skips).

CAM_ID = "11111111-1111-1111-1111-111111111111"


def _inner_coord() -> SimpleNamespace:
    """Minimal stub for `try_live_connection_inner` up to the token gate.

    `token=None` makes the inner return None immediately AFTER the force_reset
    teardown block, so the test isolates exactly that teardown.
    """
    coord = SimpleNamespace(
        live_connections={CAM_ID: {"_connection_type": "LOCAL"}},
        stream_warming={CAM_ID},
        _sessions={CAM_ID: CameraSessionState(warming_started=123.0)},
        stop_tls_proxy=AsyncMock(return_value=None),
        token=None,
    )
    coord.get_session = lambda cam_id: get_or_create_session(coord._sessions, cam_id)
    return coord


@pytest.mark.asyncio
async def test_force_reset_tears_down_under_inner():
    """force_reset=True → old session + proxy torn down inside the inner
    (i.e. under the stream lock), before any rebuild work."""
    c = _inner_coord()
    result = await try_live_connection_inner(
        c, CAM_ID, is_renewal=False, force_reset=True
    )
    assert result is None  # no token → returns after teardown
    c.stop_tls_proxy.assert_awaited_once_with(CAM_ID)
    assert CAM_ID not in c.live_connections, "force_reset must drop live session"
    assert CAM_ID not in c.stream_warming, "force_reset must clear warming flag"
    assert c._sessions[CAM_ID].warming_started == float("-inf")


@pytest.mark.asyncio
async def test_no_force_reset_no_teardown():
    """force_reset=False → inner does NOT tear down (opportunistic / renewal
    callers manage their own session state)."""
    c = _inner_coord()
    result = await try_live_connection_inner(
        c, CAM_ID, is_renewal=False, force_reset=False
    )
    assert result is None
    c.stop_tls_proxy.assert_not_awaited()
    assert CAM_ID in c.live_connections, (
        "REGRESSION: inner tore down the live session without force_reset — "
        "an opportunistic call would now kill an active stream."
    )
    assert CAM_ID in c.stream_warming


@pytest.mark.asyncio
async def test_force_reset_bypasses_lock_skip_guard():
    """When the stream lock is already held, a force_reset recovery call must
    WAIT for it (not skip) — otherwise the rescue would no-op while a renewal
    holds the lock and the 401 would never be rescued."""
    import asyncio

    lock = asyncio.Lock()
    await lock.acquire()  # simulate a renewal holding the lock

    inner_called = {"n": 0}

    async def _fake_inner(coordinator, cam_id, is_renewal=False, force_reset=False):
        inner_called["n"] += 1
        return {"_connection_type": "LOCAL"}

    c = SimpleNamespace(
        shc_state_cache={},
        get_stream_lock=lambda cid: lock,
        _ensure_go2rtc_schemes_fresh=AsyncMock(),
    )

    # try_live_connection calls the free function try_live_connection_inner
    # (imported into __init__.py's module namespace), not a coordinator
    # method — patch it there, matching where the real code looks it up.
    with patch(
        "custom_components.bosch_shc_camera.coordinator.try_live_connection_inner",
        new=_fake_inner,
    ):
        task = asyncio.ensure_future(
            BoschCameraCoordinator.try_live_connection(c, CAM_ID, force_reset=True)
        )
        await asyncio.sleep(0)  # let it reach `async with lock` and block (not skip)
        assert inner_called["n"] == 0, "force_reset call should be WAITING on the lock"
        assert not task.done(), (
            "REGRESSION: force_reset call returned early (skipped) while the lock "
            "was held — recovery must wait for the lock, never skip."
        )
        lock.release()  # renewal finished
        result = await task
    assert result == {"_connection_type": "LOCAL"}
    assert inner_called["n"] == 1


@pytest.mark.asyncio
async def test_opportunistic_call_still_skips_when_locked():
    """A plain (non-renewal, non-force) call still SKIPS when the lock is held
    — unchanged behavior, pinned so the guard relaxation didn't over-reach."""
    import asyncio

    lock = asyncio.Lock()
    await lock.acquire()

    c = SimpleNamespace(
        shc_state_cache={},
        get_stream_lock=lambda cid: lock,
        _ensure_go2rtc_schemes_fresh=AsyncMock(),
    )
    inner_mock = AsyncMock(return_value={"x": 1})
    # try_live_connection calls the free function try_live_connection_inner
    # (imported into __init__.py's module namespace), not a coordinator
    # method — patch it there, matching where the real code looks it up.
    with patch(
        "custom_components.bosch_shc_camera.coordinator.try_live_connection_inner",
        new=inner_mock,
    ):
        result = await BoschCameraCoordinator.try_live_connection(c, CAM_ID)
    # Skipped — returns the falsy STREAM_START_SKIPPED sentinel (not None) since
    # 2026-06-18 so the switch consumer can tell a benign de-dup from a real
    # failure. Still skips the inner setup (the behavior this test pins).
    from custom_components.bosch_shc_camera.const import STREAM_START_SKIPPED

    assert result is STREAM_START_SKIPPED
    assert not result
    inner_mock.assert_not_awaited()
    lock.release()


# HA's stream worker got `404 Not Found` on the old local-proxy session, then
# repeated `Connection refused` against a DIFFERENT port/session for 4+ minutes,
# with our own `camera.stream.stop() ... timed out after 5s — force-detaching`
# warning logged in between. No REMOTE-fallback escalation ever fired; only a
# manual HA restart recovered the camera.
# Root cause: `tear_down_live_stream` (idle reaper / external-privacy-detect /
# frigate-idle-timeout / REMOTE-lifetime terminator — none of them go through
# `try_live_connection`) ran WITHOUT the per-cam stream lock
# (`get_stream_lock`), while `try_live_connection`/`try_live_connection_inner`
# hold that lock across the WHOLE rebuild (PUT /connection + TLS proxy start +
# pre-warm + `Stream.update_source()`). An unlocked teardown could interleave
# mid-rebuild: the renewal publishes a brand-new proxy port into HA's `Stream`
# via `update_source()`, and a beat later the racing teardown closes that same
# port and pops `live_connections[cam_id]` — leaving the new session dead with
# zero error-counting (`record_stream_error` only counts when
# `_connection_type == "LOCAL"`, which the teardown just cleared) and therefore
# closed for the 401-rescue/threshold-escalation path (see
# test_rescue_renewal_race.py) — but `tear_down_live_stream`'s OWN callers were
# never given the same lock.
# Fix: `tear_down_live_stream` now runs its entire body under
# `self.get_stream_lock(cam_id)`, so it can no longer interleave with an
# in-flight `try_live_connection` rebuild — whichever started first runs to
# completion before the other begins.
# Follow-up (same day, adversarial verification round): locking closed the old
# race but opened a narrower one — three callers (idle reaper,
# frigate-idle-timeout, REMOTE-lifetime terminator) read stale state, DECIDE to
# tear down, then queue a call that can now block on the lock for the whole
# duration of a concurrent rebuild. By the time it wakes, the original decision
# may no longer apply to whatever session exists now (a fresh, healthy,
# unrelated-to-the-original-reason session) — teardown ran unconditionally
# regardless. Fixed by adding `expected_generation` to `tear_down_live_stream`:
# callers pass the `_auto_renew_generation` value they observed at decision
# time; teardown re-checks it FIRST thing under the lock and no-ops if a newer
# rebuild has since superseded the stale trigger.


def _make_coord():
    """Minimal coordinator stub with everything `tear_down_live_stream` touches."""
    coord = SimpleNamespace(
        _stream_locks={},
        _sessions={CAM_ID: CameraSessionState(generation=1)},
        live_connections={
            CAM_ID: {"_connection_type": "LOCAL", "rtspsUrl": "rtsps://old"}
        },
        user_intent_streams={CAM_ID},
        live_opened_at={CAM_ID: 100.0},
        stream_error_count={CAM_ID: 0},
        stream_error_at={},
        stream_fell_back={},
        local_rescue_attempts={},
        local_rescue_at={},
        stream_warming=set(),
        renewal_tasks={},
        reaper_tasks={},
        camera_entities={},
        live_stream_entities={},
        stop_tls_proxy=AsyncMock(),
        stop_viewing_front_door=AsyncMock(),
        stop_remote_viewing_front_door=AsyncMock(),
        unregister_go2rtc_stream=AsyncMock(),
        nvr_processes={},
        nvr_user_intent={},
        stop_recorder=AsyncMock(),
    )
    coord.get_stream_lock = lambda cam_id: coord._stream_locks.setdefault(
        cam_id, asyncio.Lock()
    )
    coord.get_session = lambda cam_id: get_or_create_session(coord._sessions, cam_id)
    return coord


@pytest.mark.asyncio
async def test_teardown_waits_for_renewal_holding_the_lock():
    """A concurrent renewal holding the stream lock must block teardown —
    not race it — so teardown can never pop `live_connections`/close the
    proxy while a rebuild is actively publishing a new session."""
    coord = _make_coord()
    lock = asyncio.Lock()
    coord._stream_locks[CAM_ID] = lock
    coord.get_stream_lock = lambda cam_id: coord._stream_locks[cam_id]

    await lock.acquire()  # simulate an in-flight renewal holding the lock

    task = asyncio.ensure_future(
        BoschCameraCoordinator.tear_down_live_stream(coord, CAM_ID)
    )
    await asyncio.sleep(0)  # let it reach `async with lock` and block

    assert not task.done(), (
        "REGRESSION: teardown must block on the stream lock while a renewal "
        "holds it, not run concurrently."
    )
    assert CAM_ID in coord.live_connections, (
        "REGRESSION: teardown popped live_connections while the lock was "
        "still held by a concurrent renewal — this is the exact race that "
        "left the Innenbereich camera stuck on 2026-07-04."
    )
    coord.stop_tls_proxy.assert_not_awaited()

    lock.release()  # renewal finished
    await task

    assert CAM_ID not in coord.live_connections
    coord.stop_tls_proxy.assert_awaited_once_with(CAM_ID)
    coord.unregister_go2rtc_stream.assert_awaited_once_with(CAM_ID)


@pytest.mark.asyncio
async def test_lock_spans_the_awaited_cleanup_not_just_the_pops():
    """The lock must stay held across `stop_tls_proxy`'s await, not just the
    synchronous dict pops at the top — otherwise a concurrent rebuild could
    still slip in between the pop and the proxy-stop."""
    coord = _make_coord()
    lock = asyncio.Lock()
    coord._stream_locks[CAM_ID] = lock
    coord.get_stream_lock = lambda cam_id: coord._stream_locks[cam_id]

    reached_proxy_stop = asyncio.Event()
    release_proxy_stop = asyncio.Event()

    async def _slow_stop_tls_proxy(cam_id):
        reached_proxy_stop.set()
        await release_proxy_stop.wait()

    coord.stop_tls_proxy = AsyncMock(side_effect=_slow_stop_tls_proxy)

    task = asyncio.ensure_future(
        BoschCameraCoordinator.tear_down_live_stream(coord, CAM_ID)
    )
    await reached_proxy_stop.wait()  # teardown is now inside stop_tls_proxy's await

    assert lock.locked(), (
        "REGRESSION: the stream lock was released before the awaited "
        "stop_tls_proxy cleanup finished — a concurrent try_live_connection "
        "could acquire it and race the in-progress teardown."
    )

    release_proxy_stop.set()
    await task
    assert not lock.locked()


@pytest.mark.asyncio
async def test_teardown_skips_when_session_generation_changed_since_decision():
    """A stale-intent caller (idle reaper / frigate-idle / REMOTE terminator)
    read state, decided to tear down, then queued a call that blocked on the
    lock while a concurrent rebuild ran to completion and bumped the
    generation. By the time teardown gets the lock, the ORIGINAL reason no
    longer applies to whatever session exists now — it must no-op rather
    than destroy the fresh, healthy, unrelated session."""
    coord = _make_coord()
    coord._sessions[CAM_ID].generation = 2  # a rebuild already superseded gen=1
    coord.live_connections[CAM_ID] = {
        "_connection_type": "LOCAL",
        "rtspsUrl": "rtsps://fresh-healthy-session",
    }

    await BoschCameraCoordinator.tear_down_live_stream(
        coord, CAM_ID, expected_generation=1
    )

    assert CAM_ID in coord.live_connections, (
        "REGRESSION: teardown destroyed a session from a newer generation "
        "than the stale trigger observed — it must no-op instead."
    )
    coord.stop_tls_proxy.assert_not_awaited()
    coord.unregister_go2rtc_stream.assert_not_awaited()


@pytest.mark.asyncio
async def test_teardown_proceeds_when_generation_matches():
    """Sanity check: the generation guard doesn't just always skip — it
    tears down normally when the expected generation still matches."""
    coord = _make_coord()
    await BoschCameraCoordinator.tear_down_live_stream(
        coord, CAM_ID, expected_generation=1
    )
    assert CAM_ID not in coord.live_connections
    coord.stop_tls_proxy.assert_awaited_once_with(CAM_ID)


# Tests for the FCM supervisor watchdog behavior in _async_update_data.
# With the supervisor model (v14.3.0+), the watchdog no longer manages cool-downs
# or schedules self-heals directly. Instead it just ensures the supervisor task is
# alive, spawning a new one when it is None or done(). The supervisor handles all
# retry/backoff/soft/hard-heal logic internally.
# These tests replace the old v12.8.3 retry tests which tested the now-removed
# self-heal ladder. The invariants being pinned:
# (1) FCM not running + supervisor=None → watchdog spawns supervisor
# (2) FCM running + supervisor already alive → watchdog does NOT spawn again
# (3) FCM disabled → watchdog never spawns supervisor
# (4) Healthy listener + supervisor running → no extra spawn

_PATCH_CLOUD_SESSION = (
    "custom_components.bosch_shc_camera.async_get_bosch_cloud_session"
)


class TestFcmWatchdogSupervisorSpawn:
    """Watchdog in _async_update_data must start/not-start the supervisor correctly."""

    @pytest.mark.asyncio
    async def test_not_running_supervisor_none_spawns_supervisor(self):
        """FCM enabled + supervisor=None → watchdog spawns supervisor.

        Equivalent to the old v12.8.3 "trigger (c)" test: FCM not running after
        a failed previous start (e.g. PHONE_REGISTRATION_ERROR). In the supervisor
        model the watchdog doesn't manage cooldowns — it just ensures the task exists.
        The supervisor handles backoff and retry internally.
        """
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord = _make_coord_sprint_ka(
            fcm_running=False,
            fcm_healthy=False,
            fcm_client=None,
            fcm_supervisor_task=None,
            options={"enable_fcm_push": True},
        )
        coord._first_tick_done = True

        session = _make_session_sprint_ka(
            {
                "v11/video_inputs": _make_resp(200, []),
                "feature_flags": _make_resp(200, {}),
                "protocol_support": _make_resp(200, {"state": "SUPPORTED"}),
            }
        )

        with (
            patch(_PATCH_SESSION, return_value=session),
            patch(_PATCH_CLOUD_SESSION, new=AsyncMock(return_value=session)),
            patch(
                "custom_components.bosch_shc_camera.coordinator._fcm_async_ensure_supervisor",
                new_callable=AsyncMock,
            ) as mock_ensure,
        ):
            await BoschCameraCoordinator._async_update_data(coord)

        assert mock_ensure.called, (
            "Watchdog must spawn supervisor when FCM is enabled but supervisor is None "
            "(previous start failed — supervisor will retry with backoff)"
        )

    @pytest.mark.asyncio
    async def test_supervisor_already_running_no_respawn(self):
        """Supervisor already alive (done()=False) → watchdog must NOT spawn again.

        Replaces the old "within cooldown no retry" test: if the supervisor is
        already running (doing its backoff sleep between retries), the watchdog
        must not create a duplicate.
        """
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        running_task = MagicMock(spec=asyncio.Task)
        running_task.done = MagicMock(return_value=False)

        coord = _make_coord_sprint_ka(
            fcm_running=False,
            fcm_healthy=False,
            fcm_client=None,
            fcm_supervisor_task=running_task,
            options={"enable_fcm_push": True},
        )
        coord._first_tick_done = True

        session = _make_session_sprint_ka(
            {
                "v11/video_inputs": _make_resp(200, []),
                "feature_flags": _make_resp(200, {}),
                "protocol_support": _make_resp(200, {"state": "SUPPORTED"}),
            }
        )

        with (
            patch(_PATCH_SESSION, return_value=session),
            patch(_PATCH_CLOUD_SESSION, new=AsyncMock(return_value=session)),
            patch(
                "custom_components.bosch_shc_camera.coordinator._fcm_async_ensure_supervisor",
                new_callable=AsyncMock,
            ) as mock_ensure,
        ):
            await BoschCameraCoordinator._async_update_data(coord)

        assert not mock_ensure.called, (
            "Watchdog must NOT spawn a second supervisor while one is already running "
            "— the running supervisor handles its own retry backoff"
        )

    @pytest.mark.asyncio
    async def test_fcm_disabled_no_supervisor_spawn(self):
        """enable_fcm_push=False → watchdog must NEVER spawn supervisor.

        The user explicitly disabled FCM — the watchdog must not override that.
        """
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord = _make_coord_sprint_ka(
            fcm_running=False,
            fcm_healthy=False,
            fcm_client=None,
            fcm_supervisor_task=None,
            options={"enable_fcm_push": False},
        )
        coord._first_tick_done = True

        session = _make_session_sprint_ka(
            {
                "v11/video_inputs": _make_resp(200, []),
                "feature_flags": _make_resp(200, {}),
                "protocol_support": _make_resp(200, {"state": "SUPPORTED"}),
            }
        )

        with (
            patch(_PATCH_SESSION, return_value=session),
            patch(_PATCH_CLOUD_SESSION, new=AsyncMock(return_value=session)),
            patch(
                "custom_components.bosch_shc_camera.coordinator._fcm_async_ensure_supervisor",
                new_callable=AsyncMock,
            ) as mock_ensure,
        ):
            await BoschCameraCoordinator._async_update_data(coord)

        assert not mock_ensure.called, (
            "Watchdog must NOT spawn supervisor when enable_fcm_push=False — "
            "the user opted out of FCM"
        )

    @pytest.mark.asyncio
    async def test_healthy_listener_with_running_supervisor_no_extra_spawn(self):
        """Happy path: FCM running + healthy + supervisor running → nothing extra spawned.

        Sanity check that a healthy FCM state with a live supervisor doesn't
        trigger a redundant supervisor spawn.
        """
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        running_task = MagicMock(spec=asyncio.Task)
        running_task.done = MagicMock(return_value=False)

        fcm_client = MagicMock()
        fcm_client.is_started = MagicMock(return_value=True)

        coord = _make_coord_sprint_ka(
            fcm_running=True,
            fcm_healthy=True,
            fcm_client=fcm_client,
            fcm_supervisor_task=running_task,
            options={"enable_fcm_push": True},
        )
        coord._first_tick_done = True

        session = _make_session_sprint_ka(
            {
                "v11/video_inputs": _make_resp(200, []),
                "feature_flags": _make_resp(200, {}),
                "protocol_support": _make_resp(200, {"state": "SUPPORTED"}),
            }
        )

        with (
            patch(_PATCH_SESSION, return_value=session),
            patch(_PATCH_CLOUD_SESSION, new=AsyncMock(return_value=session)),
            patch(
                "custom_components.bosch_shc_camera.coordinator._fcm_async_ensure_supervisor",
                new_callable=AsyncMock,
            ) as mock_ensure,
        ):
            await BoschCameraCoordinator._async_update_data(coord)

        assert not mock_ensure.called, (
            "Healthy listener with running supervisor must not trigger extra spawn"
        )


# Tests for the cloud-degraded rehydration helper (v12.4.10).
