# slow-tier fetch logs ("iconLedBrightness fetch error: " — 12× on Innenbereich)
# hid the actual problem. Cause: `str(asyncio.TimeoutError())` returns "".
# Fix: `err_str` helper falls back to `repr(err)` when `str(err)` is empty.


class TestErrStrHelper:
    def test_non_empty_str_passes_through(self) -> None:
        err = ValueError("bad value")
        assert BoschCameraCoordinator.err_str(err) == "bad value"

    def test_empty_str_falls_back_to_repr(self) -> None:
        err = TimeoutError()
        # str(TimeoutError()) == ""
        assert str(err) == ""
        out = BoschCameraCoordinator.err_str(err)
        assert "TimeoutError" in out

    def test_aiohttp_clienterror_empty_falls_back(self) -> None:
        err = aiohttp.ClientError()
        out = BoschCameraCoordinator.err_str(err)
        assert "ClientError" in out

    def test_handles_arbitrary_base_exception(self) -> None:
        class Custom(BaseException):
            pass

        err = Custom()
        out = BoschCameraCoordinator.err_str(err)
        assert "Custom" in out


# Tests for synchronous coordinator helper methods.
# These methods are pure-state queries (no I/O, no async) — they read from
# internal dicts and return bool/values. Highest test ROI on the
# coordinator since they're called dozens of times per coordinator tick
# from every entity's `available` and `is_on` properties.


class _StubCoord(SimpleNamespace):
    """Provides just the attributes each helper touches."""


def _make_coord_coordinator_helpers(**overrides) -> _StubCoord:
    from custom_components.bosch_shc_camera import get_options

    _entry = SimpleNamespace(
        data={"bearer_token": "tok-AAA", "refresh_token": "rfr-BBB"},
        options={"debug": False, "scan_interval": 60},
    )
    base = dict(
        data={},
        session_stale={},
        stream_warming=set(),
        entry=_entry,
        _refreshed_token=None,
        _refreshed_refresh=None,
        # mirrors BoschCameraCoordinator.__init__: snapshot taken at construction
        _options_snapshot=get_options(_entry),
    )
    base.update(overrides)
    return _StubCoord(**base)


@pytest.fixture
def bind_helpers() -> dict[str, Callable[..., Any]]:
    """Return functions that emulate the bound methods on a stub coord."""
    from custom_components.bosch_shc_camera import BoschCameraCoordinator

    return {
        "is_camera_online": BoschCameraCoordinator.is_camera_online,
        "is_session_stale": BoschCameraCoordinator.is_session_stale,
    }


def test_is_camera_online_returns_true_for_ONLINE(
    bind_helpers: dict[str, Callable[..., Any]],
) -> None:
    coord = _make_coord_coordinator_helpers(data={"cam-A": {"status": "ONLINE"}})
    assert bind_helpers["is_camera_online"](coord, "cam-A") is True


def test_is_camera_online_returns_false_for_OFFLINE(
    bind_helpers: dict[str, Callable[..., Any]],
) -> None:
    coord = _make_coord_coordinator_helpers(data={"cam-A": {"status": "OFFLINE"}})
    assert bind_helpers["is_camera_online"](coord, "cam-A") is False


