class TestShouldCheckStatus:
    """Status-check cadence: normal (every 60 s) vs offline-extended
    (every 900 s after >15 min offline). Trip-up: the offline path
    checks `per_cam_status_at` instead of the global `_last_status`."""

    def test_normal_cadence_due(self):
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        now = time.monotonic()
        coord = _make_coord_coordinator_pure_helpers(
            per_cam_status_at={CAM_A: now - 90.0}
        )
        # 90 s elapsed > 60 s interval → due
        assert (
            BoschCameraCoordinator.should_check_status(
                coord,
                CAM_A,
                now,
                60,
            )
            is True
        )

    def test_normal_cadence_not_due(self):
        """Camera checked 10s ago with interval=60s must not re-check.

        Fixed: should_check_status now uses per_cam_status_at[cam] not
        the global _last_status. With _last_status, scan_interval < interval_status
        caused _last_status to advance every tick → status never re-checked.
        """
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        now = time.monotonic()
        coord = _make_coord_coordinator_pure_helpers(
            per_cam_status_at={CAM_A: now - 10.0}
        )
        # 10 s ago < 60 s interval → not due
        assert (
            BoschCameraCoordinator.should_check_status(
                coord,
                CAM_A,
                now,
                60,
            )
            is False
        )

    def test_offline_extended_cadence(self):
        """Camera offline >15 min uses the 900 s extended interval."""
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        now = time.monotonic()
        coord = _make_coord_coordinator_pure_helpers(
            _last_status=now - 60.0,  # global status check just ran
            offline_since={CAM_A: now - 1200.0},  # offline for 20 min
            per_cam_status_at={CAM_A: now - 950.0},  # last per-cam check 950s ago
        )
        # In extended mode: per_cam_last 950s ago > 900s → due
        assert (
            BoschCameraCoordinator.should_check_status(
                coord,
                CAM_A,
                now,
                60,
            )
            is True
        )

    def test_offline_extended_blocks_premature_recheck(self):
        """A camera offline 20 min, last per-cam check 100s ago → not due
        (extended interval is 900 s, not 60 s)."""
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        now = time.monotonic()
        coord = _make_coord_coordinator_pure_helpers(
            _last_status=now - 60.0,
            offline_since={CAM_A: now - 1200.0},
            per_cam_status_at={CAM_A: now - 100.0},
        )
        assert (
            BoschCameraCoordinator.should_check_status(
                coord,
                CAM_A,
                now,
                60,
            )
            is False
        )

    def test_scan_interval_shorter_than_status_interval(self):
        """scan_interval=15s, interval_status=120s: status must fire at 120s, not every 15s.

        Bug: should_check_status used global _last_status which advanced every
        scan tick (15s). After tick 1, (now - _last_status) was always 15s < 120s
        so status was never re-checked. Fix: use per-camera per_cam_status_at.
        """
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        # Simulate: status checked at t=0, now at t=15 (scan tick fires)
        # Global _last_status just advanced to t=0 (updated on previous tick)
        now = time.monotonic()
        coord = _make_coord_coordinator_pure_helpers(
            _last_status=now - 15.0,  # advanced every 15s scan tick (bug scenario)
            per_cam_status_at={CAM_A: now - 15.0},  # last actual check was 15s ago
        )
        # interval_status=120s, only 15s elapsed → NOT due
        assert (
            BoschCameraCoordinator.should_check_status(
                coord,
                CAM_A,
                now,
                120,
            )
            is False
        ), "Status must not re-fire 15s after last check when interval is 120s"

        # Now simulate 120s later — status IS due
        coord2 = _make_coord_coordinator_pure_helpers(
            _last_status=now,  # global updated every tick (irrelevant now)
            per_cam_status_at={CAM_A: now - 125.0},  # last actual check 125s ago
        )
        assert (
            BoschCameraCoordinator.should_check_status(
                coord2,
                CAM_A,
                now,
                120,
            )
            is True
        ), "Status must fire after 125s when interval is 120s"


def _make_jwt_coordinator_pure_helpers(exp_offset_secs: int) -> str:
    """Build a fake unsigned JWT with `exp` at now + offset."""
    header = base64.urlsafe_b64encode(b'{"alg":"none"}').rstrip(b"=").decode()
    payload = (
        base64.urlsafe_b64encode(
            json.dumps({"exp": int(time.time()) + exp_offset_secs}).encode()
        )
        .rstrip(b"=")
        .decode()
    )
    return f"{header}.{payload}.sig"


def _coord_with_token(token: str) -> SimpleNamespace:
    """Stub that exposes `.token` as a plain attr so the unbound
    `_token_still_valid` (which reads `self.token`) sees the test value
    without going through the real property."""
    coord = _make_coord_coordinator_pure_helpers()
    coord.entry.data["bearer_token"] = token
    coord.token = token  # bypass the property (uses _refreshed_token logic)
    return coord


class TestTokenStillValid_coordinator_pure_helpers:
    """JWT-payload `exp` parsing — used to skip refresh when a concurrent
    caller already refreshed the token. Bug: malformed JWT must NOT
    crash the refresh path; it must return False so the refresh proceeds."""

    def test_valid_token_with_long_exp(self):
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord = _coord_with_token(_make_jwt_coordinator_pure_helpers(3600))
        assert BoschCameraCoordinator._token_still_valid(coord) is True

    def test_token_about_to_expire(self):
        """Token with 30 s remaining < default min_remaining=60 → invalid."""
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord = _coord_with_token(_make_jwt_coordinator_pure_helpers(30))
        assert BoschCameraCoordinator._token_still_valid(coord) is False

    def test_expired_token(self):
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord = _coord_with_token(_make_jwt_coordinator_pure_helpers(-3600))
        assert BoschCameraCoordinator._token_still_valid(coord) is False

    def test_empty_token(self):
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord = _coord_with_token("")
        assert BoschCameraCoordinator._token_still_valid(coord) is False

    def test_malformed_jwt_doesnt_crash(self):
        """Garbage in token field must be treated as expired, not raise."""
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord = _coord_with_token("this-is-not-a-jwt")
        assert BoschCameraCoordinator._token_still_valid(coord) is False

    def test_jwt_without_exp_field_is_invalid(self):
        """Default exp=0 in the get → very old → invalid."""
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        header = base64.urlsafe_b64encode(b'{"alg":"none"}').rstrip(b"=").decode()
        payload = base64.urlsafe_b64encode(b"{}").rstrip(b"=").decode()
        coord = _coord_with_token(f"{header}.{payload}.sig")
        assert BoschCameraCoordinator._token_still_valid(coord) is False

    def test_min_remaining_param_respected(self):
        """min_remaining=10 must accept tokens with 30 s left."""
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord = _coord_with_token(_make_jwt_coordinator_pure_helpers(30))
        assert (
            BoschCameraCoordinator._token_still_valid(coord, min_remaining=10) is True
        )
        assert (
            BoschCameraCoordinator._token_still_valid(coord, min_remaining=60) is False
        )


