class TestRefreshLocalCredsFromHeartbeat:
    """Heartbeat cred-refresh — v10.4.10 fix #1.

    Bosch's PUT /v11/video_inputs/{id}/connection LOCAL returns a fresh
    digest user/password pair on every call. The old pair stops accepting
    NEW RTSP connects within ~60 s. Without this refresh, the next
    stream-worker reconnect after idle gets HTTP 401 and trips
    LOCAL→REMOTE fallback. Capture analysis in `captures/api-findings.md`
    §1 confirmed this happens every ~333 s on Gen2 Outdoor.

    This handler runs inside the heartbeat loop; it MUST NOT crash on
    bad input (bad JSON, missing creds, missing live session) — the
    heartbeat must keep going regardless.
    """

    @staticmethod
    def _make_task_mock() -> MagicMock:
        """Return a MagicMock for hass.async_create_task that closes passed
        coroutines so the test does not emit RuntimeWarning about unawaited
        coroutines (the real HA method schedules them; our stub discards them)."""

        def _create_task(coro, *, name: str = "") -> MagicMock:
            # Close the coroutine so Python doesn't warn about it being unawaited.
            if hasattr(coro, "close"):
                coro.close()
            task = MagicMock()
            task.add_done_callback = MagicMock()
            return task

        mock = MagicMock(side_effect=_create_task)
        return mock

    def _coord(self, **overrides):
        cam_entity = SimpleNamespace(stream=None)
        base = dict(
            live_connections={
                CAM_A: {
                    "_connection_type": "LOCAL",
                    "_local_user": "old-user",
                    "_local_password": "old-pass",
                    "rtspsUrl": "rtsp://old-user:old-pass@127.0.0.1:46767/rtsp_tunnel?inst=1&enableaudio=1&fmtp=1&maxSessionDuration=3600",
                    "rtspUrl": "rtsp://old-user:old-pass@127.0.0.1:46767/rtsp_tunnel?inst=1&enableaudio=1&fmtp=1&maxSessionDuration=3600",
                },
            },
            tls_proxy_ports={CAM_A: 46767},
            local_creds_cache={},
            audio_enabled={},
            hw_version={CAM_A: "CAMERA_EYES"},
            camera_entities={CAM_A: cam_entity},
            nvr_processes={},
            nvr_user_intent={},
            # bg_tasks: set used by tracked background-task lifecycle bookkeeping.
            bg_tasks=set(),
            hass=SimpleNamespace(async_create_task=self._make_task_mock()),
            debug=False,
            get_model_config=lambda cid: SimpleNamespace(max_session_duration=3600),
            _nvr_recorder_locks={},
            # No viewing front-door bound by default — preserves the
            # pre-existing "rebuild the raw credentialed URL" behavior these
            # tests assert on. TestRefreshLocalCredsFrontDoorActive below
            # covers the front-door-bound branch explicitly.
            viewing_front_door_runner=None,
        )
        base.update(overrides)
        ns = SimpleNamespace(**base)
        if not hasattr(ns, "get_nvr_recorder_lock"):

            def _default_get_nvr_recorder_lock(cam_id: str) -> asyncio.Lock:
                lock = ns._nvr_recorder_locks.get(cam_id)
                if lock is None:
                    lock = asyncio.Lock()
                    ns._nvr_recorder_locks[cam_id] = lock
                return lock

            ns.get_nvr_recorder_lock = _default_get_nvr_recorder_lock
        return ns, cam_entity

    async def test_happy_path_updates_creds_and_url(self):
        """Fresh user+password in response → live dict + cache + URL all
        updated. The new URL must point to the same proxy port and carry
        the new creds."""
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord, _ = self._coord()
        resp = '{"user": "new-user", "password": "new-pass"}'
        await BoschCameraCoordinator.refresh_local_creds_from_heartbeat(
            coord,
            CAM_A,
            resp,
            generation=1,
            elapsed=30.0,
        )
        live = coord.live_connections[CAM_A]
        assert live["_local_user"] == "new-user"
        assert live["_local_password"] == "new-pass"
        assert "new-user" in live["rtspsUrl"]
        assert "new-pass" in live["rtspsUrl"]
        assert "127.0.0.1:46767" in live["rtspsUrl"]
        # Cache also updated
        assert coord.local_creds_cache[CAM_A]["user"] == "new-user"
        assert coord.local_creds_cache[CAM_A]["password"] == "new-pass"

    async def test_front_door_active_url_left_unchanged_creds_still_updated(self):
        """When a viewing front-door is bound for this camera, the published
        rtspsUrl/rtspUrl must NOT be overwritten with the freshly-rotated raw
        credentialed URL — the front-door's published URL is stable and
        reads creds live off _local_user/_local_password (updated here
        regardless), so re-embedding new creds into the URL on every
        heartbeat would silently re-leak them into stream_source() and
        defeat the whole point of the front-door (go2rtc's native
        registration dedupes on exact URL match and can never remove a
        stale entry)."""
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord, _ = self._coord()
        front_door_runner = MagicMock()
        front_door_runner.has_server = MagicMock(return_value=True)
        coord.viewing_front_door_runner = front_door_runner
        old_url = coord.live_connections[CAM_A]["rtspsUrl"]

        resp = '{"user": "new-user", "password": "new-pass"}'
        await BoschCameraCoordinator.refresh_local_creds_from_heartbeat(
            coord,
            CAM_A,
            resp,
            generation=1,
            elapsed=30.0,
        )
        live = coord.live_connections[CAM_A]
        # Creds ARE still updated — the front-door reads these live.
        assert live["_local_user"] == "new-user"
        assert live["_local_password"] == "new-pass"
        # Published URL is UNCHANGED (still the old, front-door-stable URL) —
        # no new creds leaked into it.
        assert live["rtspsUrl"] == old_url
        assert live["rtspUrl"] == old_url
        assert "new-user" not in live["rtspsUrl"]
        assert "new-pass" not in live["rtspsUrl"]
        front_door_runner.has_server.assert_called_once_with(CAM_A)

    async def test_front_door_inactive_url_still_rebuilt_with_new_creds(self):
        """A runner exists (feature used elsewhere) but no server is bound
        for THIS camera — must fall back to the raw-credentialed rebuild
        exactly like the no-runner-at-all case."""
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord, _ = self._coord()
        front_door_runner = MagicMock()
        front_door_runner.has_server = MagicMock(return_value=False)
        coord.viewing_front_door_runner = front_door_runner

        resp = '{"user": "new-user", "password": "new-pass"}'
        await BoschCameraCoordinator.refresh_local_creds_from_heartbeat(
            coord,
            CAM_A,
            resp,
            generation=1,
            elapsed=30.0,
        )
        live = coord.live_connections[CAM_A]
        assert "new-user" in live["rtspsUrl"]
        assert "new-pass" in live["rtspsUrl"]

    async def test_url_keeps_inst_param(self):
        """The original rtspsUrl carries `inst=1` — the rebuilt URL must
        preserve it. Bosch's session-per-instance limits mean wrong inst
        triggers concurrent-session rejection on Gen1."""
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord, _ = self._coord()
        # Override URL with inst=2
        coord.live_connections[CAM_A]["rtspsUrl"] = (
            "rtsp://old:old@127.0.0.1:46767/rtsp_tunnel?inst=2&enableaudio=1"
        )
        await BoschCameraCoordinator.refresh_local_creds_from_heartbeat(
            coord,
            CAM_A,
            '{"user": "n", "password": "p"}',
            generation=1,
            elapsed=10.0,
        )
        assert "inst=2" in coord.live_connections[CAM_A]["rtspsUrl"]

    async def test_audio_track_always_in_rebuilt_url(self):
        """The AAC track is ALWAYS requested now — switch.<cam>_audio is a synced
        card-side MUTE preference, not a stream-track toggle — so the rebuilt
        cred-rotation URL carries enableaudio=1 even when the mute is off. (This
        is what lets mute/unmute sync instantly without re-opening the stream.)"""
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord, _ = self._coord(audio_enabled={CAM_A: False})
        await BoschCameraCoordinator.refresh_local_creds_from_heartbeat(
            coord,
            CAM_A,
            '{"user": "n", "password": "p"}',
            generation=1,
            elapsed=10.0,
        )
        assert "enableaudio=1" in coord.live_connections[CAM_A]["rtspsUrl"]

    async def test_no_creds_in_response_skips_silently(self):
        """Bosch sometimes returns {} on heartbeat — must be a no-op."""
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord, _ = self._coord()
        before = dict(coord.live_connections[CAM_A])
        await BoschCameraCoordinator.refresh_local_creds_from_heartbeat(
            coord,
            CAM_A,
            "{}",
            generation=1,
            elapsed=10.0,
        )
        assert coord.live_connections[CAM_A] == before

    async def test_session_torn_down_skips(self):
        """If the live session was torn down between PUT and parse, the
        cam_id is gone from `live_connections` — must not crash."""
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord, _ = self._coord(live_connections={})
        await BoschCameraCoordinator.refresh_local_creds_from_heartbeat(
            coord,
            CAM_A,
            '{"user": "n", "password": "p"}',
            generation=1,
            elapsed=10.0,
        )
        # No exception, no mutation
        assert coord.live_connections == {}

    async def test_session_now_remote_skips(self):
        """If LOCAL fell back to REMOTE in the last second, the LOCAL
        creds are no longer relevant. Skip rather than overwrite a
        REMOTE session with rebuilt LOCAL URL."""
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord, _ = self._coord()
        coord.live_connections[CAM_A]["_connection_type"] = "REMOTE"
        before = dict(coord.live_connections[CAM_A])
        await BoschCameraCoordinator.refresh_local_creds_from_heartbeat(
            coord,
            CAM_A,
            '{"user": "n", "password": "p"}',
            generation=1,
            elapsed=10.0,
        )
        assert coord.live_connections[CAM_A]["_connection_type"] == "REMOTE"
        # creds untouched
        assert coord.live_connections[CAM_A]["_local_user"] == before["_local_user"]

    async def test_unchanged_creds_skip(self):
        """If the response carries the same user+password we already
        have, skip — no need to call Stream.update_source for nothing."""
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord, _ = self._coord()
        # Stream stub that records calls
        stream = MagicMock()
        coord.camera_entities[CAM_A].stream = stream
        await BoschCameraCoordinator.refresh_local_creds_from_heartbeat(
            coord,
            CAM_A,
            '{"user": "old-user", "password": "old-pass"}',
            generation=1,
            elapsed=10.0,
        )
        stream.update_source.assert_not_called()

    async def test_stream_update_source_called(self):
        """When creds change AND the camera entity has a Stream object,
        Stream.update_source must be called with the new URL so HA's
        stream worker rebuilds without a teardown."""
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord, _ = self._coord()
        stream = MagicMock()
        coord.camera_entities[CAM_A].stream = stream
        await BoschCameraCoordinator.refresh_local_creds_from_heartbeat(
            coord,
            CAM_A,
            '{"user": "n", "password": "p"}',
            generation=1,
            elapsed=10.0,
        )
        stream.update_source.assert_called_once()
        call_url = stream.update_source.call_args[0][0]
        assert "n:p@127.0.0.1:46767" in call_url

    async def test_stream_update_source_swallows_exceptions(self):
        """If `Stream.update_source` raises (HA bug, race), the helper
        must keep going and update the cache anyway — the next worker
        restart will pick up the cached URL."""
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord, _ = self._coord()
        stream = MagicMock()
        stream.update_source.side_effect = RuntimeError("HA stream error")
        coord.camera_entities[CAM_A].stream = stream
        # Must NOT raise
        await BoschCameraCoordinator.refresh_local_creds_from_heartbeat(
            coord,
            CAM_A,
            '{"user": "n", "password": "p"}',
            generation=1,
            elapsed=10.0,
        )
        # Cache still updated
        assert coord.local_creds_cache[CAM_A]["user"] == "n"

    async def test_no_proxy_port_skips(self):
        """If TLS proxy was stopped between PUT and parse, no port to
        point the URL at — must skip, not crash."""
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord, _ = self._coord(tls_proxy_ports={})
        await BoschCameraCoordinator.refresh_local_creds_from_heartbeat(
            coord,
            CAM_A,
            '{"user": "n", "password": "p"}',
            generation=1,
            elapsed=10.0,
        )
        # Live conn untouched
        assert coord.live_connections[CAM_A]["_local_user"] == "old-user"

    async def test_bad_json_swallowed(self):
        """The handler is best-effort — bad JSON must not crash the
        heartbeat loop. The reactive 401-rescue path is the safety net."""
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord, _ = self._coord()
        # Must NOT raise
        await BoschCameraCoordinator.refresh_local_creds_from_heartbeat(
            coord,
            CAM_A,
            "not json {{{ bad",
            generation=1,
            elapsed=10.0,
        )

    async def test_active_recorder_not_restarted_on_cred_rotation(self):
        """GitHub issue #41 regression: a heartbeat cred rotation must NOT
        restart an active NVR recorder. The docstring of
        `refresh_local_creds_from_heartbeat` itself states the established
        RTSP connection survives cred rotation — a proactive ffmpeg restart
        used to run unconditionally here, and on fast-rotating Gen1 cameras
        (15 s heartbeat) that killed/respawned ffmpeg ~4x/minute, truncating
        every recorded segment to a few seconds. Genuine ffmpeg death is
        still recovered reactively by `_watch_recorder` using the freshly
        cached `rtspsUrl` set by this same handler. The manual go2rtc
        re-registration task that used to fire here on every rotation has
        since been removed entirely (HA-core's bundled go2rtc auto-registers
        off `stream_source()` on every WebRTC offer) — no background task
        should be scheduled for a cred rotation at all now."""
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord, _ = self._coord(
            nvr_processes={CAM_A: object()},  # any non-empty value
            nvr_user_intent={CAM_A: True},
        )
        assert not hasattr(coord, "_restart_recorder_if_active")
        await BoschCameraCoordinator.refresh_local_creds_from_heartbeat(
            coord,
            CAM_A,
            '{"user": "n", "password": "p"}',
            generation=1,
            elapsed=10.0,
        )
        # No NVR restart task, no go2rtc re-register task — zero tasks now.
        assert coord.hass.async_create_task.call_count == 0


class TestFCMNoiseFilter:
    """v10.4.10 fix #2 — strips the recursive trace from
    firebase_messaging's "Unexpected exception during read" record and
    rate-limits to 1 line/60 s. Without this filter, a router reboot
    triggers ~200 lines/s of multi-thousand-line stacks until WAN comes
    back (real incident 2026-04-28: HA CPU 30 % → 85 %, coordinator
    stalled 4 min)."""

    def _record(self, msg: str, exc_text: str = "fake-trace") -> logging.LogRecord:
        rec = logging.LogRecord(
            name="firebase_messaging.fcmpushclient",
            level=logging.ERROR,
            pathname="x",
            lineno=1,
            msg=msg,
            args=None,
            exc_info=None,
        )
        rec.exc_text = exc_text
        return rec

    def test_unrelated_message_passes(self):
        from custom_components.bosch_shc_camera.fcm import _FCMNoiseFilter

        f = _FCMNoiseFilter()
        rec = self._record("Connected to FCM")
        assert f.filter(rec) is True
        # Trace not stripped
        assert rec.exc_text == "fake-trace"

    def test_target_record_first_passes_but_strips_trace(self):
        from custom_components.bosch_shc_camera.fcm import _FCMNoiseFilter

        f = _FCMNoiseFilter()
        rec = self._record("Unexpected exception during read")
        assert f.filter(rec) is True
        # Trace stripped — this is the load-bearing assertion
        assert rec.exc_info is None
        assert rec.exc_text is None

    def test_second_within_60s_dropped(self):
        from custom_components.bosch_shc_camera.fcm import _FCMNoiseFilter

        f = _FCMNoiseFilter()
        f.filter(self._record("Unexpected exception during read"))
        rec2 = self._record("Unexpected exception during read")
        assert f.filter(rec2) is False
        # Trace still stripped on dropped record (defensive — record may
        # land in another handler that doesn't use this filter).
        assert rec2.exc_info is None

    def test_install_idempotent(self):
        from custom_components.bosch_shc_camera.fcm import (
            _FCMNoiseFilter,
            _install_fcm_noise_filter,
        )

        fcm_logger = logging.getLogger("firebase_messaging.fcmpushclient")
        # Clear prior state
        for f in list(fcm_logger.filters):
            if isinstance(f, _FCMNoiseFilter):
                fcm_logger.removeFilter(f)
        _install_fcm_noise_filter()
        _install_fcm_noise_filter()
        _install_fcm_noise_filter()
        count = sum(1 for f in fcm_logger.filters if isinstance(f, _FCMNoiseFilter))
        assert count == 1
        # Cleanup
        for f in list(fcm_logger.filters):
            if isinstance(f, _FCMNoiseFilter):
                fcm_logger.removeFilter(f)


class TestModuleConstants:
    """Constants whose value matters for behaviour."""

    def test_safe_domains_locked(self):
        """The SSRF allowlist must stay narrow. Adding e.g.
        `.example.com` here would silently widen the surface."""
        from custom_components.bosch_shc_camera.coordinator import _SAFE_DOMAINS

        assert _SAFE_DOMAINS == frozenset({".boschsecurity.com", ".bosch.com"}), (
            f"_SAFE_DOMAINS changed to {_SAFE_DOMAINS} — only Bosch domains "
            "should be reachable via the resolver."
        )

    def test_safe_domains_have_leading_dot(self):
        """Each entry must start with `.` so `endswith` rejects
        lookalikes like `attacker-bosch.com`."""
        from custom_components.bosch_shc_camera.coordinator import _SAFE_DOMAINS

        for d in _SAFE_DOMAINS:
            assert d.startswith("."), (
                f"_SAFE_DOMAINS entry {d!r} missing leading '.' — "
                "endswith('boschsecurity.com') would also match "
                "'attacker-boschsecurity.com'."
            )

    def test_integration_version_string_matches_manifest(self):
        """`_INTEGRATION_VERSION` must match `manifest.json` so
        diagnostics + service-call metadata report a coherent version."""
        import json
        from pathlib import Path

        from custom_components.bosch_shc_camera import _INTEGRATION_VERSION

        manifest = json.loads(
            (
                Path(__file__).parent.parent
                / "custom_components"
                / "bosch_shc_camera"
                / "manifest.json"
            ).read_text()
        )
        assert _INTEGRATION_VERSION == manifest["version"]


