class _FakeStore_ai_describe_snapshot:
    def __init__(self, payload: Any) -> None:
        self._payload = payload

    async def async_load(self) -> Any:
        return self._payload

    async def async_save(self, data: Any) -> None:
        pass


class _MultiStore:
    def __init__(self, payloads: dict[str, Any]) -> None:
        self._payloads = payloads

    def __call__(
        self, hass: Any, *, version: int, key: str
    ) -> _FakeStore_ai_describe_snapshot:
        for suffix, payload in self._payloads.items():
            if key.endswith(suffix):
                return _FakeStore_ai_describe_snapshot(payload)
        return _FakeStore_ai_describe_snapshot(None)


