class TestAnalyzeCameraAiInvalidTarget:
    """Unknown camera_id/entity_id → ServiceValidationError(not_found),
    matching describe_snapshot's own invalid-target handling for
    consistency (describe_snapshot falls back to the first coordinator
    then raises not_found on the empty resolved_entity_id; this handler
    has no camera_entities fallback at all, so an unknown target raises
    not_found directly — same exception type/translation_key either way)."""

    @pytest.mark.asyncio
    async def test_unknown_camera_id_raises_not_found(self) -> None:
        from homeassistant.exceptions import ServiceValidationError

        hass = _make_hass_ai_describe_snapshot()
        entry = _make_entry_ai_describe_snapshot()
        coord_stub = _make_coord_stub_ai_describe_snapshot([CAM_ID], entry)
        entry.runtime_data = coord_stub
        coord_stub.entry = entry
        hass.config_entries.async_loaded_entries = MagicMock(return_value=[entry])

        handlers, _ = await _setup_and_get_handlers(hass, entry, coord_stub)
        handler = handlers["analyze_camera_ai"]

        with pytest.raises(ServiceValidationError) as exc_info:
            await handler(_make_call({"camera_id": "unknown-id"}))
        assert "not_found" in str(exc_info.value.translation_key)

    @pytest.mark.asyncio
    async def test_unknown_entity_id_raises_not_found(self) -> None:
        from homeassistant.exceptions import ServiceValidationError

        hass = _make_hass_ai_describe_snapshot()
        entry = _make_entry_ai_describe_snapshot()
        coord_stub = _make_coord_stub_ai_describe_snapshot([CAM_ID], entry)
        coord_stub.camera_entities = {}
        entry.runtime_data = coord_stub
        coord_stub.entry = entry
        hass.config_entries.async_loaded_entries = MagicMock(return_value=[entry])

        handlers, _ = await _setup_and_get_handlers(hass, entry, coord_stub)
        handler = handlers["analyze_camera_ai"]

        with pytest.raises(ServiceValidationError) as exc_info:
            await handler(_make_call({"entity_id": "camera.nonexistent"}))
        assert "not_found" in str(exc_info.value.translation_key)

    @pytest.mark.asyncio
    async def test_no_active_coordinator_raises_not_found(self) -> None:
        """All entries have runtime_data=None → ServiceValidationError(not_found).

        NOTE: unlike describe_snapshot, handle_analyze_camera_ai has no
        "fallback to first available coordinator" branch (it doesn't need
        `cur_opts` at all — the whole AI-task-options resolution describe_
        snapshot does is delegated to ai_analysis.async_generate_ai_analysis
        instead) and therefore no distinct "no active coordinator" ->
        HomeAssistantError path either: `coord` simply stays None and falls
        straight into the same `coord is None or not resolved_cam_id` guard
        used for an unknown camera_id/entity_id, both raising
        ServiceValidationError(not_found) — verified directly against the
        source (__init__.py handle_analyze_camera_ai) rather than assumed
        from describe_snapshot's shape.
        """
        from homeassistant.exceptions import ServiceValidationError

        hass = _make_hass_ai_describe_snapshot()
        entry = _make_entry_ai_describe_snapshot()
        entry.runtime_data = None
        hass.config_entries.async_loaded_entries = MagicMock(return_value=[entry])

        entry2 = _make_entry_ai_describe_snapshot()
        coord_stub = _make_coord_stub_ai_describe_snapshot([CAM_ID], entry2)
        entry2.runtime_data = coord_stub

        handlers, _ = await _setup_and_get_handlers(hass, entry2, coord_stub)
        handler = handlers["analyze_camera_ai"]

        hass.config_entries.async_loaded_entries = MagicMock(return_value=[entry])

        with pytest.raises(ServiceValidationError) as exc_info:
            await handler(_make_call({"camera_id": CAM_ID}))
        assert "not_found" in str(exc_info.value.translation_key)


# Coverage tests for `async_fetch_fresh_event_snapshot` cache fast-path.
# Exercises the lock-free cache hit branch (L3725) so a hot-path FCM-burst
# doesn't take the lock on every concurrent caller.


def _coord_fresh_event_snapshot_cache(
    cache: dict[str, tuple[bytes, float]],
) -> SimpleNamespace:
    c = SimpleNamespace()
    c._fresh_snap_cache = cache
    c._fresh_snap_locks = {}
    c.token = "TOKEN"
    c.hass = SimpleNamespace()
    return c


@pytest.mark.asyncio
class TestFreshSnapshotCacheFastPath:
    async def test_returns_cached_when_unexpired(self):
        """Fast-path: cache hit with future expiry returns immediately."""
        # Expiry far in the future relative to current monotonic clock.
        cache = {"C": (b"JPEG_DATA", float("inf"))}
        coord = _coord_fresh_event_snapshot_cache(cache)
        result = await BoschCameraCoordinator.async_fetch_fresh_event_snapshot(
            coord, "C"
        )
        assert result == b"JPEG_DATA"

    async def test_returns_none_on_expired_cache_without_token(self):
        """Stale cache + no token → fast-path falls through, slow-path bails
        on missing token. Exercises the post-fast-path token guard."""
        cache = {"C": (b"JPEG_DATA", float("-inf"))}
        coord = _coord_fresh_event_snapshot_cache(cache)
        coord.token = None  # forces the early-return after the fast path
        result = await BoschCameraCoordinator.async_fetch_fresh_event_snapshot(
            coord, "C"
        )
        assert result is None

    async def test_lock_path_recheck_hit(self):
        """Slow-path: a concurrent caller that queued on the lock must see
        the cache populated by the winner and return without another fetch.
        Simulated by stuffing the cache between the fast-path miss and the
        in-lock re-check via an awaitable lock that lets us write first."""
        cache: dict[str, tuple[bytes, float]] = {}
        coord = _coord_fresh_event_snapshot_cache(cache)

        original_lock = asyncio.Lock()

        # When acquiring the lock, populate the cache so the in-lock re-check
        # picks it up and short-circuits without any HTTP call.
        class _PopulatingLock:
            def __init__(self, target: dict[str, tuple[bytes, float]]):
                self._inner = original_lock
                self._target = target

            async def __aenter__(self):
                await self._inner.__aenter__()
                self._target["C"] = (b"CONCURRENT_DATA", float("inf"))
                return self

            async def __aexit__(self, *a):
                return await self._inner.__aexit__(*a)

        coord._fresh_snap_locks["C"] = _PopulatingLock(cache)
        result = await BoschCameraCoordinator.async_fetch_fresh_event_snapshot(
            coord, "C"
        )
        assert result == b"CONCURRENT_DATA"


# Tests for `__init__.py` async methods + thin delegation wrappers.
# Round-1B follow-up to `test_init_helpers.py`. Targets the async I/O
# methods on `BoschCameraCoordinator` that delegate to other modules
# (fcm, shc, nvr_recorder), wrap aiohttp HTTP calls, or run coordinator-
# specific lifecycle (token refresh, RCP session cache, stream worker
# error rescue, recorder gating).
# Each section pins a different contract:
# - FCM wrappers (start_fcm_push, stop_fcm_push, mark_events_read, ...)
# are thin one-liners over `fcm.async_*` — patch the imported symbol
# and assert the call signature.
# - SHC setter wrappers (async_shc_set_camera_light, async_cloud_set_*)
# are thin one-liners over `shc.*` (SHCCoordinatorMixin) — same approach.
# - `async_put_camera` runs the universal Bosch v11 PUT path with
# 401-rescue. Mock the aiohttp session.
# - `async_local_tcp_ping` wraps asyncio.open_connection. Mock it.
# - `handle_stream_worker_error` is the v10.4.10 LOCAL-rescue path —
# when HA's stream worker reports auth failure, refresh creds without
# falling back to REMOTE. Test all branches.
# - `start_recorder` / `stop_recorder` are the NVR gating wrappers from
# v11.0.4-5 (no longer includes a proactive cred-rotation restart —
# removed by the issue #41 fix, see TestRefreshLocalCredsFromHeartbeat).
# - RCP session cache + token refresh schedule round out the suite.
# These all run without HA runtime — `SimpleNamespace` for `self`,
# `MagicMock` / `AsyncMock` for collaborators.

CAM_B_async_methods = "22222222-2222-2222-2222-222222222222"


async def _noop_coro(*args, **kwargs):
    return None


def _make_coord_async_methods(**overrides):
    """Coordinator stub with the dicts most async methods touch."""

    # async_create_task gets called with a coroutine — close it to avoid
    # the "coroutine never awaited" warning, and return a MagicMock task.
    def _create_task(coro, **kwargs):
        try:
            coro.close()
        except (AttributeError, RuntimeError):
            pass
        return MagicMock(spec=asyncio.Task)

    _default_entry = SimpleNamespace(
        data={"bearer_token": "tok-A", "refresh_token": "rfr-B"},
        options={},
    )
    base = dict(
        entry=_default_entry,
        token="tok-A",
        _refreshed_token=None,
        _refreshed_refresh=None,
        _options_snapshot={
            "scan_interval": 60
        },  # mirrors coordinator __init__ snapshot
        camera_entities={},
        live_connections={},
        live_opened_at={},
        stream_error_count={},
        stream_error_at={},
        stream_fell_back={},
        local_rescue_attempts={},
        local_rescue_at={},
        renewal_tasks={},
        bg_tasks=set(),
        nvr_processes={},
        nvr_user_intent={},
        rcp_lan_ip_cache={},
        local_creds_cache={},
        rcp_session_cache={},
        rcp_session_locks={},
        lan_tcp_reachable={},
        hw_version={},
        privacy_set_at={},
        light_set_at={},
        offline_since={},
        per_cam_status_at={},
        _last_status=-86400.0,
        _OFFLINE_EXTENDED_INTERVAL=900,
        WRITE_LOCK_SECS=30.0,
        token_refresh_handle=None,
        stream_worker_dispatch_pending=None,
        stop_tls_proxy=AsyncMock(),
        stop_viewing_front_door=AsyncMock(),
        stop_remote_viewing_front_door=AsyncMock(),
        ensure_valid_token=AsyncMock(return_value="fresh-token"),
        try_live_connection=AsyncMock(return_value=None),
        record_stream_error=MagicMock(),
        # handle_stream_worker_error is invoked inside schedule_stream_worker_error
        # as `self.handle_stream_worker_error(cam_id, msg)` — must return a
        # coroutine that async_create_task can wrap. Lambda + helper keeps it simple.
        handle_stream_worker_error=lambda *a, **kw: _noop_coro(),
        get_model_config=lambda cid: SimpleNamespace(
            max_stream_errors=3, max_session_duration=3600
        ),
        is_camera_online=lambda cid: True,
        hass=SimpleNamespace(
            async_create_task=MagicMock(side_effect=_create_task),
            async_create_background_task=MagicMock(
                side_effect=lambda coro, name: _create_task(coro)
            ),
            async_add_executor_job=AsyncMock(),
            loop=SimpleNamespace(
                call_later=MagicMock(return_value=MagicMock()),
                call_soon_threadsafe=MagicMock(),
            ),
            services=SimpleNamespace(async_call=AsyncMock()),
            config=SimpleNamespace(path=lambda *a: "/tmp/x"),
            is_stopping=False,
        ),
        debug=False,
    )
    base.update(overrides)
    coord = SimpleNamespace(**base)

    def _get_rcp_session_lock(proxy_hash: str) -> asyncio.Lock:
        lock = coord.rcp_session_locks.get(proxy_hash)
        if lock is None:
            lock = asyncio.Lock()
            coord.rcp_session_locks[proxy_hash] = lock
        return lock

    coord._get_rcp_session_lock = _get_rcp_session_lock
    return coord


def _bind_method(coord, method_name: str) -> None:
    """Make a real BoschCameraCoordinator method callable on the stub.

    Useful when one method-under-test calls another bound method on
    self — bind the helper to the same SimpleNamespace stub so the
    call dispatches through real code, not a mock.
    """
    from custom_components.bosch_shc_camera import BoschCameraCoordinator

    func = getattr(BoschCameraCoordinator, method_name)
    setattr(coord, method_name, lambda *a, **kw: func(coord, *a, **kw))


def _make_jwt_async_methods(exp_offset_seconds: int) -> str:
    """Build a fake JWT whose payload's `exp` is now + offset."""
    header = base64.urlsafe_b64encode(b'{"alg":"HS256"}').rstrip(b"=").decode()
    payload_dict = {"exp": int(time.time() + exp_offset_seconds)}
    payload = (
        base64.urlsafe_b64encode(json.dumps(payload_dict).encode())
        .rstrip(b"=")
        .decode()
    )
    return f"{header}.{payload}.signature"


@asynccontextmanager
async def _aiohttp_resp(status: int = 200, body: str = ""):
    """Fake `async with` aiohttp response context manager."""
    resp = MagicMock()
    resp.status = status
    resp.json = AsyncMock(return_value=json.loads(body) if body else {})
    resp.text = AsyncMock(return_value=body)
    yield resp


def _fake_session(responses: list):
    """Build a MagicMock aiohttp session whose `.put`/`.get`/`.delete`/`.post`
    return the next response from `responses` (in order, cycling on each
    call). Each response is a `(status, body)` tuple."""
    iterator = iter(responses)

    def _make_cm(*args, **kwargs):
        try:
            status, body = next(iterator)
        except StopIteration:
            status, body = 500, ""
        return _aiohttp_resp(status, body)

    session = MagicMock()
    session.put = _make_cm
    session.get = _make_cm
    session.delete = _make_cm
    session.post = _make_cm
    return session


