class TestRecordStreamError_sprint_j1:
    """record_stream_error logs at WARNING on exactly max_stream_errors,
    and at DEBUG for every subsequent call (the 'repeat' branch).

    Line 742: `if count == cfg.max_stream_errors` → warning
    Line 747: `elif count > cfg.max_stream_errors` → debug
    """

    def test_warning_at_exact_threshold(self, caplog: pytest.LogCaptureFixture):
        """Hitting max_stream_errors exactly triggers the WARNING log."""
        import logging

        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        # max_stream_errors=3; pre-seed count to 2 so next call becomes 3
        coord = _make_coord_sprint_j1(
            stream_error_count={CAM_A: 2},
            stream_error_at={},
            live_connections={CAM_A: {"_connection_type": "LOCAL"}},
        )

        with caplog.at_level(
            logging.WARNING, logger="custom_components.bosch_shc_camera"
        ):
            BoschCameraCoordinator.record_stream_error(coord, CAM_A)

        warn_msgs = [r.message for r in caplog.records if r.levelno == logging.WARNING]
        assert any("fall back to REMOTE" in m for m in warn_msgs), (
            f"Expected WARNING about REMOTE fallback, got: {warn_msgs}"
        )
        assert coord.stream_error_count[CAM_A] == 3

    def test_debug_above_threshold(self, caplog: pytest.LogCaptureFixture):
        """Exceeding max_stream_errors triggers only the DEBUG 'repeat' log."""
        import logging

        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        # max_stream_errors=3; pre-seed count to 3 so next call becomes 4 → repeat
        coord = _make_coord_sprint_j1(
            stream_error_count={CAM_A: 3},
            stream_error_at={},
            live_connections={CAM_A: {"_connection_type": "LOCAL"}},
        )

        with caplog.at_level(
            logging.DEBUG, logger="custom_components.bosch_shc_camera"
        ):
            BoschCameraCoordinator.record_stream_error(coord, CAM_A)

        debug_msgs = [r.message for r in caplog.records if r.levelno == logging.DEBUG]
        assert any("repeat" in m for m in debug_msgs), (
            f"Expected DEBUG 'repeat' log, got: {debug_msgs}"
        )
        # No warning for the repeat call
        warn_msgs = [r.message for r in caplog.records if r.levelno == logging.WARNING]
        assert not any("fall back to REMOTE" in m for m in warn_msgs)

    def test_remote_connection_skips_count(self):
        """When current connection is REMOTE, errors are not counted."""
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord = _make_coord_sprint_j1(
            stream_error_count={},
            stream_error_at={},
            live_connections={CAM_A: {"_connection_type": "REMOTE"}},
        )

        BoschCameraCoordinator.record_stream_error(coord, CAM_A)

        # Counter must stay untouched
        assert CAM_A not in coord.stream_error_count

    def test_no_session_skips_count(self):
        """Regression: an error with no live session (connection_type None, e.g.
        a worker error firing after teardown) must NOT count — only confirmed
        LOCAL failures poison the LOCAL-vs-REMOTE decision."""
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord = _make_coord_sprint_j1(
            stream_error_count={},
            stream_error_at={},
            live_connections={},  # no session → _connection_type is None
        )

        BoschCameraCoordinator.record_stream_error(coord, CAM_A)

        assert CAM_A not in coord.stream_error_count


