class TestTryLiveConnection:
    """try_live_connection has three early-exit branches before acquiring the lock.

    Lines 2294-2298: privacy_mode active → return None (logged at INFO)
    Lines 2300-2302: lock already locked + not is_renewal → return None (WARNING)
    Lines 2308-2311: not is_renewal → _ensure_go2rtc_schemes_fresh awaited,
                     then lock acquired → try_live_connection_inner called
    """

    @pytest.mark.asyncio
    async def test_privacy_mode_returns_none(self, caplog: pytest.LogCaptureFixture):
        """When privacy_mode is active the method returns None immediately."""
        import logging

        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord = _make_coord_sprint_j1(
            shc_state_cache={CAM_A: {"privacy_mode": True}},
            _stream_locks={},
        )

        with caplog.at_level(logging.INFO, logger="custom_components.bosch_shc_camera"):
            result = await BoschCameraCoordinator.try_live_connection(coord, CAM_A)

        assert result is None
        info_msgs = [r.message for r in caplog.records if r.levelno == logging.INFO]
        assert any("privacy mode active" in m for m in info_msgs), (
            f"Expected INFO about privacy mode, got: {info_msgs}"
        )

    @pytest.mark.asyncio
    async def test_lock_already_locked_not_renewal_returns_skip_sentinel(
        self, caplog: pytest.LogCaptureFixture
    ):
        """When the per-cam lock is held and is_renewal=False, skip and return the
        STREAM_START_SKIPPED sentinel (NOT None) at DEBUG level.

        Updated 2026-06-18: the skip used to return None and log a WARNING, which
        the switch consumer mistook for a real failure ("Live stream failed" +
        intent revert + false stream-error). The skip is a benign de-dup, so it
        now returns a falsy sentinel and logs at DEBUG. See
        test_stream_start_in_progress.py for the consumer-side contract.
        """
        import logging

        from custom_components.bosch_shc_camera import BoschCameraCoordinator
        from custom_components.bosch_shc_camera.const import STREAM_START_SKIPPED

        # Create a real lock and acquire it to simulate in-progress setup
        busy_lock = asyncio.Lock()
        await busy_lock.acquire()  # lock is now held

        coord = _make_coord_sprint_j1(
            shc_state_cache={CAM_A: {}},
            _stream_locks={CAM_A: busy_lock},
        )

        with caplog.at_level(
            logging.DEBUG, logger="custom_components.bosch_shc_camera"
        ):
            result = await BoschCameraCoordinator.try_live_connection(
                coord, CAM_A, is_renewal=False
            )

        busy_lock.release()

        assert result is STREAM_START_SKIPPED
        assert not result  # falsy → existing `if result:` consumers no-op as before
        # The de-dup skip must NOT be a WARNING anymore (that was the false alarm).
        warn_msgs = [r.message for r in caplog.records if r.levelno == logging.WARNING]
        assert not any("already in progress" in m for m in warn_msgs), (
            f"Skip must not log a WARNING (false alarm), got: {warn_msgs}"
        )
        debug_msgs = [r.message for r in caplog.records if r.levelno == logging.DEBUG]
        assert any("already in progress" in m for m in debug_msgs), (
            f"Expected a DEBUG note about the in-progress skip, got: {debug_msgs}"
        )

    @pytest.mark.asyncio
    async def test_renewal_skips_warning_when_locked(self):
        """When is_renewal=True and lock is held, the method does NOT skip — it waits.

        This test confirms the asymmetry: is_renewal bypasses the skip branch and
        queues behind the lock instead.
        """
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        busy_lock = asyncio.Lock()
        # Release lock immediately so the renewal can proceed
        inner_result = {"renewed": True}

        coord = _make_coord_sprint_j1(
            shc_state_cache={CAM_A: {}},
            _stream_locks={CAM_A: busy_lock},
            _ensure_go2rtc_schemes_fresh=AsyncMock(),
        )

        # try_live_connection calls the free function try_live_connection_inner
        # (imported into __init__.py's module namespace), not a coordinator
        # method — patch it there, matching where the real code looks it up.
        with patch(
            "custom_components.bosch_shc_camera.coordinator.try_live_connection_inner",
            new=AsyncMock(return_value=inner_result),
        ):
            result = await BoschCameraCoordinator.try_live_connection(
                coord, CAM_A, is_renewal=True
            )

        assert result == inner_result

    @pytest.mark.asyncio
    async def test_not_renewal_calls_ensure_go2rtc_schemes_fresh(self):
        """When is_renewal=False, _ensure_go2rtc_schemes_fresh is awaited before the lock."""
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        ensure_fresh = AsyncMock()
        inner_result = {"connected": True}

        coord = _make_coord_sprint_j1(
            shc_state_cache={CAM_A: {}},
            _stream_locks={},
            _ensure_go2rtc_schemes_fresh=ensure_fresh,
        )

        with patch(
            "custom_components.bosch_shc_camera.coordinator.try_live_connection_inner",
            new=AsyncMock(return_value=inner_result),
        ):
            result = await BoschCameraCoordinator.try_live_connection(
                coord, CAM_A, is_renewal=False
            )

        ensure_fresh.assert_awaited_once()
        assert result == inner_result

    @pytest.mark.asyncio
    async def test_renewal_skips_ensure_go2rtc_schemes_fresh(self):
        """When is_renewal=True, _ensure_go2rtc_schemes_fresh is NOT called."""
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        ensure_fresh = AsyncMock()
        inner_result = {"connected": True}

        coord = _make_coord_sprint_j1(
            shc_state_cache={CAM_A: {}},
            _stream_locks={},
            _ensure_go2rtc_schemes_fresh=ensure_fresh,
        )

        with patch(
            "custom_components.bosch_shc_camera.coordinator.try_live_connection_inner",
            new=AsyncMock(return_value=inner_result),
        ):
            result = await BoschCameraCoordinator.try_live_connection(
                coord, CAM_A, is_renewal=True
            )

        ensure_fresh.assert_not_awaited()
        assert result == inner_result


# Targets:
# - async_fetch_live_snapshot_local: async Digest snap via async_digest_request
# - check_and_recover_webrtc: direct-refresh exception + _last_go2rtc_reload init (lines 3310-3314)
# - check_and_recover_webrtc: go2rtc reload exception + async_refresh_providers exception (lines 3335-3346)
# - _ensure_go2rtc_schemes_fresh: full flow (lines 3366-3412)
# - run_smb_cleanup_bg exception path (lines 2812-2815)
# - run_nvr_cleanup_bg exception path (lines 2850-2853)
# - async_fetch_live_snapshot: lock creation branch (lines 2886-2889) + proxy-cache eviction (line 2937)
# Each test uses SimpleNamespace coordinator stubs and calls methods as unbound functions
# via `BoschCameraCoordinator.method(coord, ...)` — no HA runtime required.

CAM_B_sprint_j2 = "22222222-2222-2222-2222-222222222222"


def _make_coord_sprint_j2(**overrides):
    """Minimal coordinator stub."""
    base = dict(
        entry=SimpleNamespace(
            entry_id="01KM38DHZ525S61HPENAT7NHC0",
            data={"bearer_token": "tok-A", "refresh_token": "rfr-B"},
            options={},
        ),
        camera_entities={},
        live_connections={},
        nvr_processes={},
        nvr_user_intent={},
        _proxy_url_cache={},
        _rcp_099e_probe_failed_until={},
        _snapshot_fetch_locks={},
        shc_state_cache={},
        local_creds_cache={},
        token="tok-A",
        hass=SimpleNamespace(
            async_add_executor_job=AsyncMock(),
            config=SimpleNamespace(path=lambda *a: "/tmp/x", config_dir="/tmp"),
            data={},
            config_entries=SimpleNamespace(
                async_reload=AsyncMock(),
                async_entries=MagicMock(return_value=[]),
            ),
        ),
        get_quality_params=MagicMock(return_value=(True, {})),
        debug=False,
    )
    base.update(overrides)
    return SimpleNamespace(**base)


def _make_digest_resp_cm(
    status: int, content_type: str = "image/jpeg", body: bytes = b""
) -> MagicMock:
    """Return an async context-manager mock for async_digest_request."""
    resp = MagicMock()
    resp.status = status
    resp.headers = {"Content-Type": content_type}
    resp.read = AsyncMock(return_value=body)
    cm = MagicMock()
    cm.__aenter__ = AsyncMock(return_value=resp)
    cm.__aexit__ = AsyncMock(return_value=None)
    # async_digest_request returns a coroutine that yields the cm
    future: asyncio.Future[MagicMock] = asyncio.get_event_loop().create_future()
    future.set_result(cm)
    return future


class TestFetchDigestClosure:
    """Tests for async_fetch_live_snapshot_local using async_digest_request.

    Strategy: patch PUT /connection to return user/password/urls, then patch
    async_digest_request to return controlled responses — no real network.
    """

    @staticmethod
    async def _run_with_mock_put(coord, cam_id, *, digest_cm_or_exc=None):
        """Wire aiohttp PUT mock + digest_request mock so the full method runs."""
        import aiohttp as _aiohttp

        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        put_resp = MagicMock()
        put_resp.status = 200
        put_resp.__aenter__ = AsyncMock(return_value=put_resp)
        put_resp.__aexit__ = AsyncMock(return_value=None)
        put_resp.text = AsyncMock(
            return_value='{"user":"u","password":"p","urls":["192.168.0.1:443"]}'
        )

        session_mock = MagicMock()
        session_mock.__aenter__ = AsyncMock(return_value=session_mock)
        session_mock.__aexit__ = AsyncMock(return_value=None)
        session_mock.put = MagicMock(return_value=put_resp)

        # async_get_clientsession returns a plain MagicMock (not the aiohttp session above)
        client_session = MagicMock()

        with (
            patch("aiohttp.TCPConnector", return_value=MagicMock()),
            patch("aiohttp.ClientSession", return_value=session_mock),
            patch(
                "custom_components.bosch_shc_camera.coordinator.async_bosch_cloud_session_cm",
                return_value=session_mock,
            ),
            patch(
                "homeassistant.helpers.aiohttp_client.async_get_clientsession",
                return_value=client_session,
            ),
            patch(
                "custom_components.bosch_shc_camera.async_digest_request",
                side_effect=digest_cm_or_exc
                if isinstance(digest_cm_or_exc, type)
                and issubclass(digest_cm_or_exc, Exception)
                else None,
                new_callable=None
                if isinstance(digest_cm_or_exc, type)
                and issubclass(digest_cm_or_exc, Exception)
                # passes an Exception type, so this lambda is never evaluated.
                else lambda: _make_patch_digest(digest_cm_or_exc),  # noqa: F821
            ),
        ):
            return await BoschCameraCoordinator.async_fetch_live_snapshot_local(
                coord, cam_id
            )

