class TestDiagnosticCloudApiOverride:
    """The advanced 'diagnostic_cloud_api_override' field must reach every
    video_inputs URL the coordinator builds — not silently ignored.

    Regression for the 2026-07-06 beta-backend-environment hypothesis
    (Thomas): a single account might be registered on a different Bosch
    camera-API backend than production; this diagnostic switch is the only
    way to test that without touching Bosch's non-production infrastructure
    ourselves.
    """

    @pytest.mark.asyncio
    async def test_override_base_used_for_video_inputs_url(self):
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        override = "https://example-diagnostic-override.invalid"
        coord = _make_coord_sprint_ka(_cloud_api=override)
        coord._first_tick_done = True

        called_urls = []

        def _get(url, **kwargs):
            called_urls.append(url)
            if "video_inputs" in url and "ping" not in url:
                return _make_resp(200, [])
            return _make_resp(200, {})

        session_mock = MagicMock()
        session_mock.get = MagicMock(side_effect=_get)

        with patch(_PATCH_SESSION, new=AsyncMock(return_value=session_mock)):
            await BoschCameraCoordinator._async_update_data(coord)

        video_input_calls = [u for u in called_urls if "video_inputs" in u]
        assert video_input_calls, "video_inputs must have been called at all"
        assert all(u.startswith(override) for u in video_input_calls), (
            f"video_inputs URL must use the override base, got: {video_input_calls}"
        )
        assert not any(
            urlparse(u).hostname == "residential.cbs.boschsecurity.com"
            for u in video_input_calls
        ), "override must replace, not add to, the default production base"

    def test_coordinator_init_uses_default_when_no_override(self):
        """No cloud_api_override in entry.data → falls back to the real CLOUD_API constant."""
        from homeassistant.config_entries import ConfigEntry

        from custom_components.bosch_shc_camera import CLOUD_API, BoschCameraCoordinator

        entry = MagicMock(spec=ConfigEntry)
        entry.data = {"bearer_token": "tok-A", "refresh_token": "rfr-B"}
        entry.options = {}

        coord = BoschCameraCoordinator.__new__(BoschCameraCoordinator)
        coord.entry = entry
        cloud_api_override = entry.data.get("cloud_api_override", "")
        coord._cloud_api = cloud_api_override or CLOUD_API

        assert coord._cloud_api == CLOUD_API

    def test_coordinator_init_uses_override_when_present(self):
        """cloud_api_override in entry.data → replaces the default CLOUD_API constant."""
        from homeassistant.config_entries import ConfigEntry

        from custom_components.bosch_shc_camera import CLOUD_API, BoschCameraCoordinator

        override = "https://custom-backend.example.invalid"
        entry = MagicMock(spec=ConfigEntry)
        entry.data = {
            "bearer_token": "tok-A",
            "refresh_token": "rfr-B",
            "cloud_api_override": override,
        }
        entry.options = {}

        coord = BoschCameraCoordinator.__new__(BoschCameraCoordinator)
        coord.entry = entry
        cloud_api_override = entry.data.get("cloud_api_override", "")
        coord._cloud_api = cloud_api_override or CLOUD_API

        assert coord._cloud_api == override
        assert coord._cloud_api != CLOUD_API


class TestCameraList401DoubleFailure:
    """Lines 1388-1392: both calls return 401 → ConfigEntryAuthFailed with 'Token expired'.

    ConfigEntryAuthFailed (not UpdateFailed) so HA starts the native reauth
    flow instead of retrying this non-transient condition forever
    (backported from the Core PR's Copilot review round 3, 2026-07-27).
    """

    @pytest.mark.asyncio
    async def test_401_retry_401_raises_update_failed(self):
        """Both video_inputs calls return 401 → ConfigEntryAuthFailed containing 'Token expired'."""
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord = _make_coord_sprint_ka()
        coord._first_tick_done = True

        call_count = [0]

        def _get(url, **kwargs):
            if "v11/video_inputs" in url and "ping" not in url:
                call_count[0] += 1
                return _make_resp(401, None)
            return _make_resp(200, {})

        session_mock = MagicMock()
        session_mock.get = MagicMock(side_effect=_get)

        with (
            pytest.raises(ConfigEntryAuthFailed, match="Token expired"),
            patch(_PATCH_SESSION, new=AsyncMock(return_value=session_mock)),
        ):
            await BoschCameraCoordinator._async_update_data(coord)

        assert call_count[0] == 2, (
            "Both 401 calls must have been made (initial + retry)"
        )

    @pytest.mark.asyncio
    async def test_401_bodies_logged_at_debug_for_diagnosis(
        self, caplog: pytest.LogCaptureFixture
    ):
        """Bosch's 401 response body must be captured at DEBUG on both attempts.

        Regression for 2026-07-06 SebastianHarder community report: after v14.4.4
        the coordinator still logged the generic "Token expired and renewal
        failed" every tick with no way to see *why* Bosch rejected a freshly
        renewed token. Neither call's response body was ever surfaced.
        """
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord = _make_coord_sprint_ka()
        coord._first_tick_done = True

        call_count = [0]

        def _get(url, **kwargs):
            if "v11/video_inputs" in url and "ping" not in url:
                call_count[0] += 1
                return _make_resp(
                    401,
                    None,
                    text_data=f'{{"error":"consent_required_{call_count[0]}"}}',
                )
            return _make_resp(200, {})

        session_mock = MagicMock()
        session_mock.get = MagicMock(side_effect=_get)

        with (
            caplog.at_level(logging.DEBUG, logger="custom_components.bosch_shc_camera"),
            pytest.raises(ConfigEntryAuthFailed, match="Token expired"),
            patch(_PATCH_SESSION, new=AsyncMock(return_value=session_mock)),
        ):
            await BoschCameraCoordinator._async_update_data(coord)

        debug_msgs = [r.message for r in caplog.records if r.levelno == logging.DEBUG]
        assert any("consent_required_1" in m for m in debug_msgs), (
            f"First 401 body must be logged at DEBUG, got: {debug_msgs}"
        )
        assert any("consent_required_2" in m for m in debug_msgs), (
            f"Retry 401 body must be logged at DEBUG, got: {debug_msgs}"
        )

    @pytest.mark.asyncio
    async def test_sh_authorization_failed_raises_account_permission_message(self):
        """Bosch's 'sh:authorization.failed' body must not be reported as a token problem.

        Regression for 2026-07-06 SebastianHarder community report: debug
        logging (added this same release) revealed that a freshly-renewed,
        Keycloak-accepted token was still rejected by the camera API with
        {"error":"sh:authorization.failed","message":"missing permission
        \"user is registered\""} — an account/permission issue on Bosch's
        side, not a token problem. Telling the user to re-authenticate is
        actively misleading here (he had already done so, repeatedly).
        """
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord = _make_coord_sprint_ka()
        coord._first_tick_done = True

        def _get(url, **kwargs):
            if "v11/video_inputs" in url and "ping" not in url:
                return _make_resp(
                    401,
                    None,
                    text_data=(
                        '{"status":401,"error":"sh:authorization.failed",'
                        '"message":"missing permission \\"user is registered\\"",'
                        '"description":null,"href":null}'
                    ),
                )
            return _make_resp(200, {})

        session_mock = MagicMock()
        session_mock.get = MagicMock(side_effect=_get)

        with (
            pytest.raises(UpdateFailed, match="account/permission issue") as exc_info,
            patch(_PATCH_SESSION, new=AsyncMock(return_value=session_mock)),
        ):
            await BoschCameraCoordinator._async_update_data(coord)

        message = str(exc_info.value)
        assert "sh:authorization.failed" in message
        assert "user is registered" in message
        assert "Re-authenticating will not fix it" in message
        assert "official Bosch Smart Camera App" in message


