class TestPanFetch:
    """Lines 1851-1862: pan endpoint called when panLimit > 0 and ONLINE."""

    @pytest.mark.asyncio
    async def test_pan_fetch_when_pan_limit_nonzero_online(self):
        """featureSupport.panLimit > 0, status ONLINE → pan endpoint fetched, pan_cache updated."""
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        cam_entry = _make_cam_entry_sprint_lb(
            CAM_A,
            featureSupport={"light": False, "panLimit": 180},
        )
        pan_data = {"currentAbsolutePosition": 45}

        coord = _make_coord_sprint_lb(
            hw_version={CAM_A: "HOME_Eyes_Outdoor"},
            cached_status={CAM_A: "ONLINE"},
            pan_cache={},
            shc_state_cache={
                CAM_A: {
                    "device_id": None,
                    "camera_light": None,
                    "front_light": None,
                    "wallwasher": None,
                    "front_light_intensity": None,
                    "privacy_mode": False,
                    "has_light": False,
                    "notifications_status": None,
                }
            },
            should_check_status=MagicMock(return_value=False),
        )

        pan_urls_called = []

        def _get(url, **kwargs):
            url_str = str(url)
            if "/pan" in url_str:
                pan_urls_called.append(url_str)
