def _model_cfg_sprint_lc(**overrides):
    """Return a SimpleNamespace that mimics a ModelConfig dataclass."""
    base = dict(
        max_stream_errors=3,
        min_wifi_for_local=50,
        max_session_duration=3600,
        generation=2,
        display_name="Eyes Außenkamera II",
        pre_warm_delay=0,
        pre_warm_retries=2,
        pre_warm_retry_wait=1,
        post_warm_buffer=0,
        describe_timeout=5,
        min_total_wait=0,
    )
    base.update(overrides)
    return SimpleNamespace(**base)


def _make_coord_live(**overrides):
    """Minimal coordinator stub for try_live_connection_inner tests."""
    task_mock = MagicMock()
    task_mock.done = MagicMock(return_value=True)

    def _create_task(coro, **kwargs):
        import inspect

        if inspect.iscoroutine(coro):
            coro.close()
        return task_mock

    base = dict(
        token="tok-A",
        entry=SimpleNamespace(
            data={"bearer_token": "tok-A", "refresh_token": "rfr-B"},
            options={"stream_connection_type": "auto"},
        ),
        stream_type_override=None,
        stream_error_count={},
        stream_error_at={},
        stream_fell_back={},
        local_promote_at={},
        lan_tcp_reachable={},
        rcp_lan_ip_cache={CAM_A: "192.168.1.1"},
        local_creds_cache={},
        tls_proxy_ports={},
        hw_version={CAM_A: "HOME_Eyes_Outdoor"},
        wifiinfo_cache={},
        audio_enabled={},
        live_connections={},
        live_opened_at={},
        stream_warming=set(),
        _sessions={},
        camera_entities={},
        zombie_stream_worker_count={},
        bg_tasks=set(),
        renewal_tasks={},
        reaper_tasks={},
        nvr_user_intent={},
        nvr_processes={},
        nvr_preroll_processes={},
        nvr_preroll_tasks={},
        async_local_tcp_ping=AsyncMock(return_value=False),
        start_tls_proxy=AsyncMock(return_value=12345),
        stop_tls_proxy=AsyncMock(),
        stop_viewing_front_door=AsyncMock(),
        stop_remote_viewing_front_door=AsyncMock(),
        # Default: front-door bind "fails" (returns None) so
        # try_live_connection_inner falls back to the raw credentialed URL —
        # preserves this fixture's pre-existing rtspsUrl assertions.
        start_viewing_front_door=AsyncMock(return_value=None),
        start_remote_viewing_front_door=AsyncMock(return_value=None),
        check_and_recover_webrtc=AsyncMock(),
        auto_renew_local_session=AsyncMock(return_value=None),
        idle_session_reaper=AsyncMock(return_value=None),
        remote_session_terminator=AsyncMock(return_value=None),
        refresh_rcp_state=AsyncMock(return_value=None),
        async_request_refresh=AsyncMock(return_value=None),
        # Stream-start latency fix (2026-07-17): the fresh-toggle path calls
        # this synchronous method directly instead of scheduling a full
        # async_request_refresh via async_create_task.
        async_update_listeners=MagicMock(),
        get_quality_params=MagicMock(return_value=(True, 1)),
        get_quality=MagicMock(return_value="auto"),
        _quality_effective_inst={},
        get_model_config=MagicMock(return_value=_model_cfg_sprint_lc()),
        hass=SimpleNamespace(
            async_create_task=_create_task,
            async_add_executor_job=AsyncMock(),
            data={},
            # try_live_connection_inner now goes through the pooled
            # cloud_ssl.async_get_bosch_cloud_session (WP1,
            # stream-perf-stability-refactor) — on first use (hass.data
            # empty) it registers an EVENT_HOMEASSISTANT_STOP close
            # listener via hass.bus.async_listen_once.
            bus=SimpleNamespace(async_listen_once=MagicMock()),
        ),
        debug=False,
        get_cam_lan_ip=MagicMock(return_value="192.168.1.1"),
    )
    base.update(overrides)
    coord = SimpleNamespace(**base)
    coord.get_session = lambda cam_id: get_or_create_session(coord._sessions, cam_id)

    def replace_renewal_task(cam_id, coro):
        t = coord.hass.async_create_task(coro)
        coord.renewal_tasks[cam_id] = t
        return t

    coord.replace_renewal_task = replace_renewal_task
    coord.replace_reaper_task = replace_renewal_task
    return coord


class TestRemoteInst4Reduced:
    """Line 2437: REMOTE, inst=4 → inst overridden to 2 before PUT."""

    @pytest.mark.asyncio
    async def test_remote_inst4_reduced_to_2(self):
        """get_quality_params returns inst=4, REMOTE → PUT body highQualityVideo with inst=2 internally (no 400 error)."""
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        # get_quality_params returns inst=4, which REMOTE doesn't support
        coord = _make_coord_live(
            entry=SimpleNamespace(
                data={"bearer_token": "tok-A"},
                options={"stream_connection_type": "remote"},
            ),
            get_quality_params=MagicMock(return_value=(True, 4)),
        )

        remote_body = json.dumps(
            {
                "urls": ["proxy-01.live.cbs.boschsecurity.com:42090/hashXXX"],
                "bufferingTime": 1000,
            }
        )
        resp = _put_resp(200, remote_body)
        session_mock = MagicMock()
        session_mock.close = AsyncMock()
        session_mock.put = AsyncMock(return_value=resp)

        with (
            patch("aiohttp.TCPConnector", return_value=MagicMock()),
            patch("aiohttp.ClientSession", return_value=session_mock),
        ):
            result = await try_live_connection_inner(coord, CAM_A)

        # Method should succeed (no 400 because inst was reduced to 2)
        assert result is not None, "REMOTE with inst=4→2 reduction must succeed"
        # PUT must have been called
        assert session_mock.put.called, "PUT must be called"


