# All tests use unbound-method or minimal-stub patterns — no live HA runtime.

CAM_B_sprint_md = "22222222-AAAA-BBBB-CCCC-000000000002"


class _FakeStore_sprint_md:
    """A Store stub whose async_load returns a preset payload."""

    def __init__(self, payload: Any) -> None:
        self._payload = payload
        self.saved: list[Any] = []

    async def async_load(self) -> Any:
        return self._payload

    async def async_save(self, data: Any) -> None:
        self.saved.append(data)


class _MultiStore_sprint_md:
    """Factory that returns per-key _FakeStore_sprint_md instances.

    Pass `payloads={key_suffix: payload}` where key_suffix matches the
    trailing part of the Store `key=` kwarg.
    """

    def __init__(self, payloads: dict[str, Any]) -> None:
        self._payloads = payloads
        self.stores: dict[str, _FakeStore_sprint_md] = {}

    def __call__(
        self, hass: Any, *, version: int, key: str, private: bool = False
    ) -> _FakeStore_sprint_md:
        """Called as Store(hass, version=1, key=..., private=...)."""
        for suffix, payload in self._payloads.items():
            if key.endswith(suffix):
                store = _FakeStore_sprint_md(payload)
                self.stores[key] = store
                return store
        store = _FakeStore_sprint_md(None)
        self.stores[key] = store
        return store


