def _resp_cm_round8(
    status: int, text: str = "", body: bytes = b"", headers: dict | None = None
):
    resp = MagicMock()
    resp.status = status
    resp.text = AsyncMock(return_value=text)
    resp.read = AsyncMock(return_value=body or text.encode())
    resp.json = AsyncMock(return_value={})
    resp.headers = headers or {}
    cm = MagicMock()
    cm.__aenter__ = AsyncMock(return_value=resp)
    cm.__aexit__ = AsyncMock(return_value=None)
    return cm


def _stub_coord_round8(**kwargs):
    hass = MagicMock()
    generation_override = kwargs.pop("_auto_renew_generation", None)
    idle_since_override = kwargs.pop("_session_idle_since", None)
    sessions = dict(kwargs.pop("_sessions", {}))
    if generation_override is not None:
        for cam_id, gen in generation_override.items():
            sessions.setdefault(cam_id, CameraSessionState()).generation = gen
    if idle_since_override is not None:
        for cam_id, val in idle_since_override.items():
            sessions.setdefault(cam_id, CameraSessionState()).idle_since = val
    coord = SimpleNamespace(
        token="test-token",
        hass=hass,
        entry=SimpleNamespace(entry_id="01ENTRY"),
        live_connections={},
        _rcp_state_cache={},
        camera_entities={},
        _sessions=sessions,
        session_stale={},
        renewal_tasks={},
        reaper_tasks={},
        _auto_renew_tasks={},
        last_schemes_refresh=float("-inf"),
        _last_go2rtc_reload=float("-inf"),
        _proxy_url_cache={},
        _options_snapshot={},
    )
    coord.get_model_config = MagicMock()
    coord.try_live_connection = AsyncMock(return_value=None)
    coord.refresh_local_creds_from_heartbeat = AsyncMock()
    coord._ensure_go2rtc_schemes_fresh = AsyncMock()
    coord.get_session = lambda cam_id: get_or_create_session(coord._sessions, cam_id)
    for k, v in kwargs.items():
        setattr(coord, k, v)
    return coord


class TestRefreshRcpState_round8:
    def _bind(self, coord):
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord.refresh_rcp_state = types.MethodType(
            BoschCameraCoordinator.refresh_rcp_state, coord
        )
        return coord

    @pytest.mark.asyncio
    async def test_empty_cache_no_update(self):
        """Empty _rcp_state_cache → setdefault returns {} → if cache: skipped."""
        coord = self._bind(_stub_coord_round8())
        await coord.refresh_rcp_state(CAM_ID)
        # cache stays empty (setdefault returns {}, falsy → no assignment)
        assert coord._rcp_state_cache.get(CAM_ID) == {}

    @pytest.mark.asyncio
    async def test_non_empty_cache_updated(self):
        """Pre-populated cache → source + fetched_at are written."""
        coord = self._bind(
            _stub_coord_round8(
                _rcp_state_cache={CAM_ID: {"some_key": "val"}},
                live_connections={CAM_ID: {"_connection_type": "LOCAL"}},
            )
        )
        await coord.refresh_rcp_state(CAM_ID)
        cache = coord._rcp_state_cache[CAM_ID]
        assert cache["source"] == "local"
        assert "fetched_at" in cache

    @pytest.mark.asyncio
    async def test_no_live_connection_uses_question_mark(self):
        """No active connection → source derived from '?' → stored as '?'."""
        coord = self._bind(
            _stub_coord_round8(
                _rcp_state_cache={CAM_ID: {"old": True}},
                live_connections={},
            )
        )
        await coord.refresh_rcp_state(CAM_ID)
        assert coord._rcp_state_cache[CAM_ID]["source"] == "?"


