def _make_resp_scattered_coverage(status: int, json_data=None, text_data: str = ""):
    resp = MagicMock()
    resp.status = status
    resp.json = AsyncMock(return_value=json_data if json_data is not None else {})
    resp.text = AsyncMock(return_value=text_data)
    resp.__aenter__ = AsyncMock(return_value=resp)
    resp.__aexit__ = AsyncMock(return_value=None)
    return resp


def _make_session_fn_scattered_coverage(url_routes: dict):
    state: dict = {
        k: (list(v) if isinstance(v, list) else [v]) for k, v in url_routes.items()
    }
    sorted_patterns = sorted(state.keys(), key=len, reverse=True)

    def _get(url, **kwargs):
        for pattern in sorted_patterns:
            if pattern in url:
                queue = state[pattern]
                if queue:
                    r = queue.pop(0)
                    if not queue:
                        queue.append(r)
                    return r
        return _make_resp_scattered_coverage(200, [])

    session = MagicMock()
    session.get = MagicMock(side_effect=_get)
    return session


