class TestSendEventWebhookNoLoadedEntries:
    """Lines 6342-6343: When no entries are loaded for DOMAIN, handler
    logs a warning and returns early."""

    @pytest.mark.asyncio
    async def test_no_entries_logs_warning_and_returns(self):
        """async_loaded_entries returns [] → warning + return (lines 6342-6343)."""
        from custom_components.bosch_shc_camera import async_setup_entry

        store_factory = _MultiStore_sprint_md(
            {
                k: None
                for k in [
                    "_maint_notified",
                    "_cloud_alert_state",
                    "_lan_ips",
                    "_hw_versions",
                    "_local_creds",
                ]
            }
        )

        hass = _make_hass_sprint_md()
        entry = _make_entry_sprint_md(options={})
        coord_stub = _make_coord_stub_sprint_md([CAM_ID_coverage_gaps_v13])
        coord_stub.data = {CAM_ID_coverage_gaps_v13: {"info": {"title": "Terrasse"}}}

        captured_handler = []

        def _register_service(domain, service, handler, **kwargs):
            if service == "send_event_webhook":
                captured_handler.append(handler)

        hass.services.async_register = MagicMock(side_effect=_register_service)
        hass.services.has_service = MagicMock(return_value=False)

        # Return empty list: no entries loaded for DOMAIN → lines 6341-6343
        hass.config_entries.async_loaded_entries = MagicMock(return_value=[])

        with (
            patch(f"{MODULE}.BoschCameraCoordinator", return_value=coord_stub),
            patch("homeassistant.helpers.storage.Store", side_effect=store_factory),
            patch(f"{MODULE}.cf_unbuffer.register"),
            patch(
                "homeassistant.helpers.entity_registry.async_get",
                return_value=_make_ent_reg(),
            ),
            patch(
                f"{MODULE}.async_get_bosch_cloud_session",
                new=AsyncMock(return_value=MagicMock()),
            ),
        ):
            await async_setup_entry(hass, entry)

        assert captured_handler, "Service handler must be registered"
        handler = captured_handler[0]

        logged_warnings = []

        with patch(f"{MODULE}._LOGGER") as mock_log:
            mock_log.warning.side_effect = lambda *a, **k: logged_warnings.append(a)
            call = SimpleNamespace(data={"event_type": "MOVEMENT", "entity_id": ""})
            await handler(call)

        # Lines 6342-6343: warning logged, early return
        no_entries_warnings = [
            w for w in logged_warnings if "no loaded entries" in str(w).lower()
        ]
        assert no_entries_warnings, (
            "Must log 'no loaded entries' warning when no entries for domain (lines 6342-6343)"
        )


class TestAsyncCancelCoordinatorTasksBreak:
    """Line 6454: When live_connections is non-empty but tear_down_live_stream
    is None (getattr returns None), the loop breaks immediately."""

    @pytest.mark.asyncio
    async def test_no_teardown_method_breaks_loop(self):
        """live_connections non-empty but no tear_down_live_stream → break (line 6454)."""
        from custom_components.bosch_shc_camera import _async_cancel_coordinator_tasks

        task = MagicMock()
        task.done.return_value = False
        task.cancel = MagicMock()

        coord = SimpleNamespace(
            async_stop_fcm_push=AsyncMock(),
            token_refresh_handle=None,
            renewal_tasks={},
            reaper_tasks={},
            bg_tasks=set(),
            nvr_drain_task=None,
            tls_proxy_ports={},
            stream_log_listener=None,
            live_connections={
                CAM_ID_coverage_gaps_v13: {"rtspsUrl": "rtsps://cam/stream"}
            },
            # No tear_down_live_stream → getattr returns None → break fires
        )
        assert not hasattr(coord, "tear_down_live_stream"), (
            "Test precondition: tear_down_live_stream must be absent"
        )

        with (
            patch(f"{MODULE}.nvr_recorder.stop_all", AsyncMock()),
            patch(f"{MODULE}.stop_all_proxies"),
            patch("asyncio.gather", AsyncMock(return_value=[])),
        ):
            # Must complete without error (break fires, loop exits cleanly)
            await _async_cancel_coordinator_tasks(coord)


# Regression tests for HA backend bugs fixed in v13.6.1 (round-2 bug hunt).
# Covers:
# H2  — handle_create_rule / handle_delete_rule missing empty-cam/rule_id guard
# H3  — handle_update_rule PUT URL missing /{rule_id}
# H4  — BoschCameraLastEventSensor UTC timestamp (was treated as local)
# M4  — handle_set_privacy_masks coordinate range [0.0, 1.0] validation
# M5  — handle_rename_camera hardcoded Europe/Berlin timezone
# M6  — BoschCameraStatusSensor unknown status passthrough
# M7  — number.py available false-negative at level 0
# M8  — select.py current_option returns default (+ warning) for unknown enum
# L1  — handle_invite_friend logs only email domain
# L2  — BoschCameraEventsTodaySensor UTC date bucket
# M2  — diagnostics TO_REDACT covers smb_share + smb_base_path
# M3  — diagnostics cameras dicts routed through async_redact_data

RULE_ID = "rule-abc-123"


def _make_hass_backend_round2_fixes(time_zone: str = "America/New_York"):
    hass = MagicMock()
    hass.services.has_service.return_value = False
    hass.services.async_register = MagicMock()
    hass.services.async_call = AsyncMock()
    hass.config_entries.async_loaded_entries.return_value = []
    hass.async_create_task = MagicMock()
    hass.config.time_zone = time_zone
    return hass


def _entry_with_coord_backend_round2_fixes(**coord_kwargs):
    """Returns (entry, coord) tuple matching the real test pattern."""
    coord = MagicMock()
    coord.token = "tok-A"
    coord.async_request_refresh = AsyncMock()
    coord.rules_cache = {}
    for k, v in coord_kwargs.items():
        setattr(coord, k, v)
    entry = MagicMock()
    entry.runtime_data = coord
    return entry, coord


def _call_backend_round2_fixes(data):
    call = MagicMock()
    call.data = data
    return call


def _make_session_backend_round2_fixes(resp_cm):
    session = MagicMock()
    session.post = MagicMock(return_value=resp_cm)
    session.put = MagicMock(return_value=resp_cm)
    session.get = MagicMock(return_value=resp_cm)
    session.delete = MagicMock(return_value=resp_cm)
    return session


def _register_and_get_handlers(hass, session=None):
    """Call _register_services and return the handler dict."""
    from custom_components.bosch_shc_camera import _register_services

    _register_services(hass)
    return _get_handlers(hass)


