class TestStreamSupportNoiseFilterSentinel:
    """`_StreamSupportNoiseFilter.filter` must default unseen entities to
    float('-inf') (SENTINEL_RULE), not 0.0, or the first log line on a
    low-monotonic host is incorrectly filtered."""

    def test_filter_uses_neg_inf_default(self):
        import inspect

        import custom_components.bosch_shc_camera.__init__ as _m

        src = inspect.getsource(_m._StreamSupportNoiseFilter.filter)
        assert "_last_passed.get(ent, 0.0)" not in src, (
            "_StreamSupportNoiseFilter.filter must not use 0.0 as default — "
            "SENTINEL_RULE: use float('-inf') for time.monotonic() comparisons"
        )
        assert_in_source(src, "float('-inf')", 'float("-inf")', any_of=True)

    def test_filter_passes_new_entity_at_low_monotonic(self):
        import logging

        from custom_components.bosch_shc_camera.__init__ import (
            _StreamSupportNoiseFilter,
        )

        f = _StreamSupportNoiseFilter()
        record = logging.LogRecord(
            name="homeassistant.components.camera.bosch_terrasse",
            level=logging.WARNING,
            pathname="",
            lineno=0,
            msg="test",
            args=(),
            exc_info=None,
        )

        with patch(
            "custom_components.bosch_shc_camera.__init__._StreamSupportNoiseFilter.filter",
            wraps=f.filter,
        ):
            with patch("time.monotonic", return_value=5.0):
                import time as _time_mod

                orig = _time_mod.monotonic
                _time_mod.monotonic = lambda: 5.0
                try:
                    result = f.filter(record)
                finally:
                    _time_mod.monotonic = orig

        assert result is True, (
            "At monotonic=5s, a new entity must not be filtered by the "
            "float('-inf') sentinel default"
        )


class TestAnyStatusCheckedFix:
    """`any_status_checked` must be set unconditionally once a non-exception
    status result is processed — re-gating it on a fresh `should_check_status`
    call after `_check_one_camera_status` already stamped
    `per_cam_status_at[cid]=now` always returns False for extended-offline
    cameras, causing a redundant status-check gather on every subsequent tick.

    Premise updated (2026-07, Phase 2 step 4): this logic lives in
    `camera_status.py::poll_statuses` now, not inline in
    `_async_update_data` — see camera_status.py's own module docstring for
    the same explanation, carried over verbatim during the extraction.
    """

    def test_any_status_checked_set_unconditionally(self):
        import inspect

        import custom_components.bosch_shc_camera.camera_status as _m

        src = inspect.getsource(_m.poll_statuses)

        block_start = src.find("any_status_checked = False")
        assert block_start != -1, "any_status_checked pattern must exist"

        stale_pattern = "if coordinator.should_check_status(cid, now, interval_status):\n                    any_status_checked = True"
        assert stale_pattern not in src, (
            "any_status_checked must NOT be gated on should_check_status re-eval "
            "after gather — per_cam_status_at[cid] was just set to `now` inside "
            "_check_one_camera_status, so re-eval always returns False for "
            "extended-offline cams"
        )

        correct_pattern = "any_status_checked = True"
        tail = src[block_start:]
        assert correct_pattern in tail, (
            "any_status_checked must be set to True unconditionally when a "
            "non-exception result is processed from status_results"
        )

    def test_comment_explains_fix(self):
        import inspect

        import custom_components.bosch_shc_camera.camera_status as _m

        src = inspect.getsource(_m.poll_statuses)
        assert "per_cam_status_at" in src and "any_status_checked" in src, (
            "The fix comment must reference per_cam_status_at to explain "
            "why the stale re-evaluation was incorrect"
        )


class TestAlertSentIdsSentinel:
    """`alert_sent_ids.get(newest_id, ...)` must default to float('-inf')
    (SENTINEL_RULE). With a 0.0 default, `0.0 > (now - 60)` is True whenever
    monotonic() < 60s (fresh host boot), suppressing the very first motion
    alert for every previously-unseen event ID."""

    def test_alert_sent_ids_default_not_zero(self):
        import inspect

        import custom_components.bosch_shc_camera.event_dispatch as _m

        src = inspect.getsource(_m)
        assert "alert_sent_ids.get(newest_id, 0.0)" not in src, (
            "event_dispatch.py must not use 0.0 as default for alert_sent_ids.get(); "
            "on hosts with monotonic < 60s, 0.0 > (now-60) is True → first alert suppressed"
        )

    def test_alert_sent_ids_uses_neginf_default(self):
        import inspect

        import custom_components.bosch_shc_camera.event_dispatch as _m

        src = inspect.getsource(_m)
        assert_in_source(src, 'alert_sent_ids.get(newest_id, float("-inf"))')

    def test_dedup_not_triggered_for_new_id_at_low_monotonic(self):
        low_monotonic_now = 30.0

        old_default = 0.0
        new_default = float("-inf")

        old_dedup = old_default > (low_monotonic_now - 60.0)
        new_dedup = new_default > (low_monotonic_now - 60.0)

        assert old_dedup is True, (
            "0.0 default causes dedup skip at low monotonic (demonstrates bug)"
        )
        assert new_dedup is False, (
            "float('-inf') default must not trigger dedup for unseen event IDs"
        )

    def test_dedup_still_fires_for_recently_seen_id(self):
        now = 200.0
        recently_sent = now - 30.0

        dedup = recently_sent > (now - 60.0)
        assert dedup is True, (
            "Recently-seen ID must still be deduped within the 60s window"
        )


class TestHeartbeatRenewalFailsReset:
    """A heartbeat-forced session renewal that succeeds must reset
    `renewal_fails` to 0 — otherwise a prior streak of ≥3 time-based renewal
    failures keeps `renewal_fails >= 3` set, marking a healthy session as
    stale (`session_stale=True`) on the very next time-based check."""

    def test_heartbeat_renewal_resets_renewal_fails(self):
        import inspect

        import custom_components.bosch_shc_camera.session_renewal as _m

        src = inspect.getsource(_m)
        heartbeat_block_marker = "Heartbeat: session renewed for"
        idx = src.find(heartbeat_block_marker)
        assert idx != -1, (
            "Heartbeat renewal log message not found in session_renewal.py "
            "(moved from __init__.py in the Phase 3 step 2 refactor)"
        )
        nearby = src[idx : idx + 600]
        nearby_norm = " ".join(nearby.replace("(", " ").replace(")", " ").split())
        assert "renewal_fails = 0" in nearby_norm, (
            "After heartbeat-forced renewal success, renewal_fails must be reset to 0. "
            "Without this, a prior renewal_fails ≥ 3 count causes session_stale=True "
            "on the next time-based renewal check — marking a healthy session as stale."
        )


