class TestFetchLiveSnapshotLocalValueError:
    """`BoschCameraCoordinator.async_fetch_live_snapshot_local` must catch
    ValueError from async_digest_request (e.g. a 401 without a WWW-Authenticate
    header during a half-rotated Digest state) and return None instead of
    letting it propagate up the cloud-fetch caller chain and surface as an
    HA-core HTTP 500 (forum report, Andrew75, 2026-05-15).

    The sibling regression for `camera.py:_async_camera_image_impl`'s own
    LOCAL Digest branch (the entity-side call path) lives in
    tests/test_camera.py::TestCameraImageImplValueError."""

    def _put_resp_cm(self, status: int, body_json: dict):
        import json as _json

        resp = MagicMock()
        resp.status = status
        resp.text = AsyncMock(return_value=_json.dumps(body_json))
        cm = MagicMock()
        cm.__aenter__ = AsyncMock(return_value=resp)
        cm.__aexit__ = AsyncMock(return_value=None)
        return cm

    @pytest.mark.asyncio
    async def test_value_error_returns_none(self):
        from custom_components.bosch_shc_camera import (
            BoschCameraCoordinator,
        )

        coord = BoschCameraCoordinator.__new__(BoschCameraCoordinator)
        coord.shc_state_cache = {}
        coord._refreshed_token = "tok"
        coord.entry = SimpleNamespace(data={"bearer_token": "tok"}, options={})
        coord.get_quality_params = MagicMock(return_value=("720p", "low"))
        coord.hass = SimpleNamespace(data={})
        coord.local_creds_cache = {}

        put_cm = self._put_resp_cm(
            200,
            {"user": "cbs-1", "password": "p", "urls": ["192.0.2.1:443"]},
        )
        mock_session = MagicMock()
        mock_session.put = MagicMock(return_value=put_cm)
        session_cm = MagicMock()
        session_cm.__aenter__ = AsyncMock(return_value=mock_session)
        session_cm.__aexit__ = AsyncMock(return_value=None)

        lan_session = MagicMock()
        with (
            patch(
                "custom_components.bosch_shc_camera.aiohttp.ClientSession",
                return_value=session_cm,
            ),
            patch(
                "custom_components.bosch_shc_camera.coordinator.async_get_bosch_cloud_ssl_context",
                new=AsyncMock(return_value=False),
            ),
            patch(
                "homeassistant.helpers.aiohttp_client.async_get_clientsession",
                return_value=lan_session,
            ),
            patch(
                "custom_components.bosch_shc_camera.async_digest_request",
                new=AsyncMock(
                    side_effect=ValueError(
                        "Server returned 401 without WWW-Authenticate header for "
                        "'https://192.0.2.1:443/snap.jpg?JpegSize=1206'"
                    )
                ),
            ),
        ):
            out = await coord.async_fetch_live_snapshot_local(CAM_ID)
        assert out is None


# Section: `_refresh_token_locked` (OAuth refresh path) — relocated from
# tests/test_init_token_refresh.py


def _make_coord_token_refresh(**overrides):
    """Coordinator stub with everything `_refresh_token_locked` reads."""

    def _create_task(coro, **kwargs):
        try:
            coro.close()
        except (AttributeError, RuntimeError):
            pass
        return MagicMock(spec=asyncio.Task)

    base = dict(
        entry=SimpleNamespace(
            data={"bearer_token": "tok-OLD", "refresh_token": "rfr-OLD"},
            options={},
        ),
        _refreshed_token=None,
        _refreshed_refresh=None,
        auth_outage_count=0,
        _auth_outage_next_retry_ts=float("-inf"),  # SENTINEL_RULE
        _auth_outage_alert_sent=False,
        _token_fail_count=0,
        _token_timeout_fail_count=0,
        _token_alert_sent=False,
        _token_still_valid=lambda min_remaining=60: False,
        schedule_token_refresh=MagicMock(),
        hass=SimpleNamespace(
            async_create_task=MagicMock(side_effect=_create_task),
            config_entries=SimpleNamespace(async_update_entry=MagicMock()),
        ),
        debug=False,
    )
    base.update(overrides)
    stub = SimpleNamespace(**base)
    # SimpleNamespace has no MRO to TokenAuthCoordinatorMixin, so
    # `self._handle_successful_refresh(...)` inside `_refresh_token_locked`
    # would otherwise AttributeError — bind the real method onto the stub
    # (backported from the Core PR's Copilot review round 5, 2026-07-27).
    from custom_components.bosch_shc_camera.token_auth import (
        TokenAuthCoordinatorMixin,
    )

    stub._handle_successful_refresh = types.MethodType(
        TokenAuthCoordinatorMixin._handle_successful_refresh, stub
    )
    return stub


class TestTokenRefreshEarlyReturns:
    @pytest.mark.asyncio
    async def test_returns_existing_token_when_still_valid(self):
        """No observed_token given (legacy callers) → fall back to the
        JWT-expiry heuristic. Another caller may have already refreshed
        while we waited on the lock. Skip the POST."""
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord = _make_coord_token_refresh(
            _token_still_valid=lambda min_remaining=60: True
        )
        coord.token = "still-valid-tok"
        out = await BoschCameraCoordinator._refresh_token_locked(coord)
        assert out == "still-valid-tok"

    @pytest.mark.asyncio
    async def test_skips_refresh_when_token_already_changed_since_observed(self):
        """observed_token given + self.token already differs → a
        concurrent caller refreshed while we waited on the lock. Skip
        the POST and reuse their result."""
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord = _make_coord_token_refresh()
        coord.token = "tok-refreshed-by-someone-else"
        out = await BoschCameraCoordinator._refresh_token_locked(
            coord, "tok-that-got-401"
        )
        assert out == "tok-refreshed-by-someone-else"

    @pytest.mark.asyncio
    async def test_attempts_refresh_when_observed_token_still_current_even_if_jwt_unexpired(
        self,
    ):
        """A token can be rejected by Bosch (rotated/early-invalidated) well
        before its own JWT `exp` claim says so. Passing `observed_token`
        must force an actual refresh attempt instead of trusting
        `_token_still_valid` and resending the same dead token forever."""
        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord = _make_coord_token_refresh(
            _token_still_valid=lambda min_remaining=60: True
        )
        coord.token = "tok-that-got-401"
        new_tokens = {"access_token": "tok-NEW", "refresh_token": "rfr-NEW"}
        with (
            patch(
                "custom_components.bosch_shc_camera.async_get_bosch_cloud_session",
                new=AsyncMock(return_value=MagicMock()),
            ),
            patch(
                "custom_components.bosch_shc_camera.config_flow._do_refresh",
                new=AsyncMock(return_value=new_tokens),
            ) as do_refresh,
        ):
            out = await BoschCameraCoordinator._refresh_token_locked(
                coord, "tok-that-got-401"
            )
        do_refresh.assert_awaited_once()
        assert out == "tok-NEW"

    @pytest.mark.asyncio
    async def test_outage_cooldown_raises_update_failed(self):
        """In the back-off window after an outage, raise UpdateFailed
        instead of POSTing — avoids hammering a known-down server."""
        from homeassistant.helpers.update_coordinator import UpdateFailed

        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        future = time.monotonic() + 60
        coord = _make_coord_token_refresh(
            auth_outage_count=2,
            _auth_outage_next_retry_ts=future,
        )
        with pytest.raises(UpdateFailed) as exc:
            await BoschCameraCoordinator._refresh_token_locked(coord)
        assert "outage" in str(exc.value).lower()

    @pytest.mark.asyncio
    async def test_no_refresh_token_raises_config_entry_auth_failed(self):
        """No refresh token at all → trigger HA's reauth flow."""
        from homeassistant.exceptions import ConfigEntryAuthFailed

        from custom_components.bosch_shc_camera import BoschCameraCoordinator

        coord = _make_coord_token_refresh(
            entry=SimpleNamespace(data={}, options={}),
        )
        with pytest.raises(ConfigEntryAuthFailed) as exc:
            await BoschCameraCoordinator._refresh_token_locked(coord)
        assert "re-authentication" in str(exc.value).lower()


